		public static global::Dpr.Battle.Logic.Handler.Waza.HandlerGetFunc getHandlerGetFunc(global::Pml.WazaNo waza) {
        	for (int i = 0; i < GET_FUNC_TABLE.Length; i++)
        	{
        		if (GET_FUNC_TABLE[i].waza == waza)
        			return GET_FUNC_TABLE[i].func;
        	}
        	return null;
        }
		public static bool Add(global::Dpr.Battle.Logic.EventSystem pEventSystem, global::Dpr.Battle.Logic.BTL_POKEPARAM poke, global::Pml.WazaNo waza, uint subPri) {
			HandlerGetFunc func = getHandlerGetFunc(waza);
			if (func == null)
				return false;

			byte dependID = poke.GetID();
			if (!canRegister(pEventSystem, dependID, waza))
				return false;

			EventFactor.EventHandlerTable[] handlerTable = func.Invoke();
			if (handlerTable == null)
				return false;

			pEventSystem.AddFactor(EventFactorType.WAZA, (ushort)waza, EventPriority.WAZA, subPri, dependID, handlerTable, (byte)handlerTable.Length);
			return true;
		}
		public static bool canRegister(global::Dpr.Battle.Logic.EventSystem pEventSystem, byte pokeID, global::Pml.WazaNo waza) {
			EventFactorContainer container = pEventSystem.GetFactorContainer();
			EventFactor factor = container.SeekFactor(EventFactorType.WAZA, pokeID);
			int count = 0;
			while (factor != null)
			{
				if (factor.GetSubID() == (ushort)waza)
					return false;
				if (count >= EVENT_WAZA_STICK_MAX)
					return false;
				factor = container.GetNextFactor(factor, false);
				count++;
			}
			return true;
		}
		public static void Remove(global::Dpr.Battle.Logic.EventSystem pEventSystem, global::Dpr.Battle.Logic.BTL_POKEPARAM poke, global::Pml.WazaNo waza) {
			// 017f9840: GetID first, container read once, the next WAZA factor of the same dependID is fetched BEFORE the
			// current one may be removed; a factor is removed only when its sub ID matches and its stick work slot is 0
			byte dependID = poke.GetID();
			EventFactorContainer container = pEventSystem.GetFactorContainer();
			EventFactor factor = container.SeekFactor(EventFactorType.WAZA, dependID);
			while (factor != null)
			{
				EventFactor next = container.GetNextFactor(factor, false);
				if (factor.GetSubID() == (ushort)waza && factor.GetWorkValue(WORKIDX_STICK) == FALSE)
					pEventSystem.RemoveFactor(factor);
				factor = next;
			}
		}
		public static void RemoveForce(global::Dpr.Battle.Logic.EventSystem pEventSystem, global::Dpr.Battle.Logic.BTL_POKEPARAM poke, global::Pml.WazaNo waza) {
			removeHandlerForce(pEventSystem, poke.GetID(), waza);
		}
		public static void removeHandlerForce(global::Dpr.Battle.Logic.EventSystem pEventSystem, byte pokeID, global::Pml.WazaNo waza) {
			// 017f99a0: after a removal the search RESTARTS with SeekFactor (no stick check here)
			EventFactorContainer container = pEventSystem.GetFactorContainer();
			EventFactor factor = container.SeekFactor(EventFactorType.WAZA, pokeID);
			while (factor != null)
			{
				if (factor.GetSubID() == (ushort)waza)
				{
					pEventSystem.RemoveFactor(factor);
					factor = container.SeekFactor(EventFactorType.WAZA, pokeID);
				}
				else
				{
					factor = container.GetNextFactor(factor, false);
				}
			}
		}
		public static void RemoveForceAll(global::Dpr.Battle.Logic.EventSystem eventSystem, global::Dpr.Battle.Logic.BTL_POKEPARAM poke) {
			byte pokeID = poke.GetID();
			EventFactorContainer container = eventSystem.GetFactorContainer();
			EventFactor factor = container.SeekFactor(EventFactorType.WAZA, pokeID);
			while (factor != null)
			{
				eventSystem.RemoveFactor(factor);
				factor = container.SeekFactor(EventFactorType.WAZA, pokeID);
			}
		}
