		public static void handler_Texture(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			byte type = WAZADATA.GetType(bpp.WAZA_GetID(0));
			if (bpp.IsMatchType(type))
				return;
			var desc = new Section_FromEvent_ChangePokeType.Description();
			desc.pokeID = pokeID;
			desc.nextType = PokeTypePair.MakePure(type);
			desc.exTypeCause = BTL_POKEPARAM.ExTypeCause.EXTYPE_CAUSE_NONE;
			if (Common.ChangeType(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
