		public static void handler_TrickRoom(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			bool result;
			if (Common.CheckFieldEffect(args, EffectType.EFF_TRICKROOM))
			{
				var removeDesc = new Section_FromEvent_FieldEffect_Remove.Description();
				removeDesc.effect = EffectType.EFF_TRICKROOM;
				result = Common.RemoveFieldEffect(args, removeDesc);
			}
			else
			{
				var addDesc = new Section_FieldEffect_Add.Description();
				addDesc.pokeID = pokeID;
				addDesc.effect = EffectType.EFF_TRICKROOM;
				addDesc.cont = SICKCONT.MakeTurn(pokeID, 5);
				addDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TrickRoom);
				addDesc.successMessage.AddArg(pokeID);
				result = Common.AddFieldEffect(args, addDesc);
			}
			if (result)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
