		public static void handler_Kiribarai(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);

			var rankDesc = new Section_FromEvent_RankEffect.Description();
			rankDesc.pokeID = pokeID;
			rankDesc.rankType = WazaRankEffect.AVOID;
			rankDesc.rankVolume = -1;
			rankDesc.targetPokeCount = 1;
			rankDesc.targetPokeID[0] = targetPokeID;
			rankDesc.isSpFailMessageDisplay = true;
			rankDesc.byWazaEffect = true;
			bool rankResult = Common.RankEffect(args, rankDesc);

			// 017fab28: byte loop counter over every side effect (`and #0xff ; cmp #0x16`)
			var defDesc = new Section_SideEffect_Remove.Description();
			defDesc.pokeID = pokeID;
			defDesc.side = Common.PokeIDtoSide(args, targetPokeID);
			calc.BITFLG_Construction(defDesc.flags);
			for (byte eff = (byte)BtlSideEffect.BTL_SIDEEFF_START; eff < (byte)BtlSideEffect.BTL_SIDEEFF_MAX; eff++)
			{
				if (tables.IsKiriBaraiEnable_DefenderSide((BtlSideEffect)eff))
					calc.BITFLG_Set(defDesc.flags, eff);
			}
			bool defResult = Common.RemoveSideEffect(args, defDesc);

			var atkDesc = new Section_SideEffect_Remove.Description();
			atkDesc.pokeID = pokeID;
			atkDesc.side = Common.PokeIDtoSide(args, pokeID);
			calc.BITFLG_Construction(atkDesc.flags);
			for (byte eff = (byte)BtlSideEffect.BTL_SIDEEFF_START; eff < (byte)BtlSideEffect.BTL_SIDEEFF_MAX; eff++)
			{
				if (tables.IsKiriBaraiEnable_AttackerSide((BtlSideEffect)eff))
					calc.BITFLG_Set(atkDesc.flags, eff);
			}
			bool atkResult = Common.RemoveSideEffect(args, atkDesc);

			bool groundResult = false;
			if (Common.CheckFieldEffect(args, EffectType.EFF_GROUND))
			{
				var groundDesc = new Section_FromEvent_FieldEffect_Remove.Description();
				groundDesc.effect = EffectType.EFF_GROUND;
				groundResult = Common.RemoveFieldEffect(args, groundDesc);
			}

			if (rankResult || defResult || atkResult || groundResult)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
