		public static void handler_Kawarawari_DmgDetermine(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BtlSide side = args.pMainModule.PokeIDtoSide((byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF));
			if (!Side.IsExist(args.pEventSystem, side, BtlSideEffect.BTL_SIDEEFF_REFLECTOR) &&
				!Side.IsExist(args.pEventSystem, side, BtlSideEffect.BTL_SIDEEFF_HIKARINOKABE) &&
				!Side.IsExist(args.pEventSystem, side, BtlSideEffect.BTL_SIDEEFF_AURORAVEIL))
				return;

			var removeDesc = new Section_SideEffect_Remove.Description();
			removeDesc.pokeID = pokeID;
			removeDesc.side = side;
			calc.BITFLG_Construction(removeDesc.flags);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_REFLECTOR);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_HIKARINOKABE);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_AURORAVEIL);
			Common.RemoveSideEffect(args, removeDesc);

			// 017fb224: built in place (no common_SetWazaEffectIndex init flag 0x4cbb8eb in this method)
			var effDesc = new Section_FromEvent_SetWazaEffectIndex.Description();
			effDesc.effectIndex = 1;
			Common.SetWazaEffectIndex(args, effDesc);
		}
		public static bool handler_Kawarawari_SkipCheck(in global::Dpr.Battle.Logic.EventFactor.SkipCheckHandlerArgs args) {
			if (args.factorType != EventFactorType.SIDE)
				return false;
			BtlSideEffect effect = (BtlSideEffect)args.subID;
			return effect == BtlSideEffect.BTL_SIDEEFF_REFLECTOR || effect == BtlSideEffect.BTL_SIDEEFF_HIKARINOKABE || effect == BtlSideEffect.BTL_SIDEEFF_AURORAVEIL;
		}
