		}
		public static void handler_Monomane(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.HENSIN_Check())
				return;
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1));
			if (tables.IsGWaza(target.GetPrevWazaID()))
				return;
			WazaNo waza = target.GetPrevOrgWazaID();
			if (waza == WazaNo.NULL)
				return;
			if (tables.IsMatchMonomaneFail(waza))
				return;
			if (tables.IsGWaza(waza))
				return;
			if (bpp.WAZA_SearchIdx(waza) != BattleDefConst.PTL_WAZA_MAX)
				return;
			byte wazaIdx = bpp.WAZA_SearchIdx((WazaNo)Common.GetSubID(args));
			if (wazaIdx == BattleDefConst.PTL_WAZA_MAX)
				return;

			var updateDesc = new Section_FromEvent_UpdateWaza.Description();
			updateDesc.pokeID = pokeID;
			updateDesc.wazaIdx = wazaIdx;
			updateDesc.waza = waza;
			updateDesc.ppMax = 0;
			updateDesc.isPermanent = false;
			Common.UpdateWaza(args, updateDesc);

			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Monomane);
			msgDesc.message.AddArg(pokeID);
			msgDesc.message.AddArg((int)waza);
			Common.Message(args, msgDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Sketch() {
			return HandlerTable_Sketch;
		}
		public static void handler_Sketch(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			byte wazaIdx = bpp.WAZA_SearchIdx((WazaNo)Common.GetSubID(args));
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1));
			WazaNo waza = sketch_GetTargetWaza(target);
			if (waza == WazaNo.WARUAGAKI || waza == WazaNo.SUKETTI || waza == WazaNo.NULL || waza == WazaNo.OSYABERI)
				return;
			if (bpp.WAZA_IsUsable(waza))
				return;
			// 017fb9ac: HENSIN_Check is called before the index test
			if (bpp.HENSIN_Check() || wazaIdx == BattleDefConst.PTL_WAZA_MAX)
				return;

			var updateDesc = new Section_FromEvent_UpdateWaza.Description();
			updateDesc.pokeID = pokeID;
			updateDesc.wazaIdx = wazaIdx;
			updateDesc.waza = waza;
			updateDesc.ppMax = 0;
			updateDesc.isPermanent = true;
			Common.UpdateWaza(args, updateDesc);

			// 017fba34: the message description's pokeID is never set (as shipped)
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Monomane);
			msgDesc.message.AddArg(pokeID);
			msgDesc.message.AddArg((int)waza);
			Common.Message(args, msgDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
