		public static void handler_Noroi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.IsMatchType((byte)PokeType.GHOST))
			{
				var agiDesc = new Section_FromEvent_RankEffect.Description();
				agiDesc.pokeID = pokeID;
				agiDesc.targetPokeCount = 1;
				agiDesc.targetPokeID[0] = pokeID;
				agiDesc.rankType = WazaRankEffect.AGILITY;
				agiDesc.rankVolume = -1;
				agiDesc.byWazaEffect = true;
				bool agiResult = Common.RankEffect(args, agiDesc);

				var atkDesc = new Section_FromEvent_RankEffect.Description();
				atkDesc.pokeID = pokeID;
				atkDesc.targetPokeCount = 1;
				atkDesc.targetPokeID[0] = pokeID;
				atkDesc.rankType = WazaRankEffect.ATTACK;
				atkDesc.rankVolume = 1;
				atkDesc.byWazaEffect = true;
				bool atkResult = Common.RankEffect(args, atkDesc);

				var defDesc = new Section_FromEvent_RankEffect.Description();
				defDesc.pokeID = pokeID;
				defDesc.targetPokeCount = 1;
				defDesc.targetPokeID[0] = pokeID;
				defDesc.rankType = WazaRankEffect.DEFENCE;
				defDesc.rankVolume = 1;
				defDesc.byWazaEffect = true;
				bool defResult = Common.RankEffect(args, defDesc);

				var effDesc = new Section_FromEvent_SetWazaEffectIndex.Description();
				effDesc.effectIndex = 0;
				Common.SetWazaEffectIndex(args, effDesc);

				if (agiResult || atkResult || defResult)
					Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
				return;
			}

			// ghost type: curse the target for half of the user's max HP
			if (bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP) > 0)
			{
				byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
				if (targetPokeID != PokeID.INVALID)
				{
					var sickDesc = new Section_AddSick.Description();
					sickDesc.pokeID = pokeID;
					sickDesc.targetPokeID = targetPokeID;
					sickDesc.sickID = WazaSick.WAZASICK_NOROI;
					sickDesc.sickCont = SICKCONT.MakePermanent(pokeID);
					sickDesc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Noroi);
					sickDesc.specialMessage.AddArg(pokeID);
					sickDesc.specialMessage.AddArg(targetPokeID);
					if (Common.AddSick(args, sickDesc))
					{
						var hpDesc = new Section_FromEvent_ShiftHP.Description();
						hpDesc.pokeID = pokeID;
						hpDesc.targetPokeCount = 1;
						hpDesc.targetPokeID[0] = pokeID;
						hpDesc.volume[0] = -(int)calc.QuotMaxHP(bpp, 2, true);
						hpDesc.damageCause = DamageCause.NOROI;
						Common.ShiftHP(args, hpDesc);
						Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
					}
				}
			}
			var ghostEffDesc = new Section_FromEvent_SetWazaEffectIndex.Description();
			ghostEffDesc.effectIndex = 1;
			Common.SetWazaEffectIndex(args, ghostEffDesc);
		}
