		public static void handler_TriAttack(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// InitializeArray @ global-metadata 0x667C2D = {1, 4, 3}; the random index is a byte (`and #0xff`)
			Pml.PokePara.Sick[] sickTable = new Pml.PokePara.Sick[] { Pml.PokePara.Sick.MAHI, Pml.PokePara.Sick.YAKEDO, Pml.PokePara.Sick.KOORI };
			byte idx = (byte)calc.GetRand((uint)sickTable.Length);
			Pml.PokePara.Sick sick = sickTable[idx];
			Common.RewriteEventVar(args, EventVar.Label.SICKID, (int)sick);
			Common.RewriteEventVar(args, EventVar.Label.ADD_PER, 20);
			BTL_SICKCONT cont = calc.MakeDefaultPokeSickCont(sick, pokeID, false);
			BTL_SICKCONTOBJ contObj = (BTL_SICKCONTOBJ)Common.GetEventVarAddress(args, EventVar.Label.SICK_CONT_ADRS);
			contObj.value = cont;
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Nettou() {
