		}
		public static void handler_Nettou(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// 017fdcd0: `cbz count` then an equality loop = an unsigned count
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			for (int i = 0; i < targetCount; i++)
			{
				byte targetPokeID = (byte)Common.GetEventVar(args, (EventVar.Label)((int)EventVar.Label.POKEID_TARGET1 + i));
				BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
				if (target.IsDead() || !target.CheckSick(WazaSick.WAZASICK_KOORI))
					continue;
				var desc = new Section_CureSick.Description();
				desc.sick = (WazaSickEx)WazaSick.WAZASICK_KOORI;
				desc.targetPokeCount = 1;
				desc.targetPokeID[0] = targetPokeID;
				desc.pokeID = pokeID;
				Common.CureSick(args, desc);
			}
		}
