				return;
			if (Common.GetEventVar(args, EventVar.Label.SICKID) != (int)WazaSick.WAZASICK_BIND)
				return;
			WazaNo waza = (WazaNo)Common.GetSubID(args);
			byte defPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			// makituku_GetStr inlined (Waza class-init test, same compare tree)
			if (makituku_GetStr(out ushort strID, waza))
			{
				StrParam strParam = (StrParam)Common.GetEventVarAddress(args, EventVar.Label.WORK_ADRS);
				strParam.Setup(BtlStrType.BTL_STRTYPE_SET, strID);
				strParam.AddArg(defPokeID);
				strParam.AddArg(pokeID);
			}
		}
		public static bool makituku_GetStr(out ushort pStrID, global::Pml.WazaNo wazano) {
			switch (wazano)
			{
				case WazaNo.SIMETUKERU:
					pStrID = BTL_STRID_SET.Simetukeru_Start;
					return true;
				case WazaNo.MAKITUKU:
					pStrID = BTL_STRID_SET.Makituku_Start;
					return true;
				case WazaNo.HONOONOUZU:
					pStrID = BTL_STRID_SET.HonoNoUzu_Start;
					return true;
				case WazaNo.KARADEHASAMU:
					pStrID = BTL_STRID_SET.KaradeHasamu_Start;
					return true;
				case WazaNo.UZUSIO:
					pStrID = BTL_STRID_SET.Uzusio_Start;
					return true;
				case WazaNo.SUNAZIGOKU:
					pStrID = BTL_STRID_SET.Sunajigoku_Start;
					return true;
				case WazaNo.MAGUMASUTOOMU:
					pStrID = BTL_STRID_SET.MagmaStorm_Start;
					return true;
				case WazaNo.MATOWARITUKU:
					pStrID = BTL_STRID_SET.Matowarituku_Start;
					return true;
				case WazaNo.TORABASAMI:
					pStrID = BTL_STRID_SET.Torabasami;
					return true;
				default:
					pStrID = BTL_STRID_SET.Invalid;
					return false;
			}
		}
