		public static void handler_IkariNoMaeba(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF));
			// 017fea5c: Waza class-init test + the folded body `(ushort)hp >> 1`, 0 -> 1 = inlined common_CalcFixDamageByDefenderHp
			Common.RewriteEventVar(args, EventVar.Label.FIX_DAMAGE, common_CalcFixDamageByDefenderHp(target, 1, 2));
			Common.RewriteEventVar(args, EventVar.Label.FIX_DAMAGE_FLAG, TRUE);
		}
		public static ushort common_CalcFixDamageByDefenderHp(global::Dpr.Battle.Logic.BTL_POKEPARAM target, byte numerator, byte denominator) {
			uint hp = (ushort)target.GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G);
			// 017feb10: unguarded `udiv` — ARM64 yields 0 for a zero denominator
			uint damage = denominator != 0 ? hp * numerator / denominator : 0;
			if ((ushort)damage == 0)
				return 1;
			return (ushort)damage;
		}
