		public static void handler_Gamusyara(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF));
			int damage = target.GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G) - attacker.GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G);
			// 017fedcc: `csinc ge` — a negative difference becomes 1 (0 stays 0)
			if (damage < 0)
				damage = 1;
			Common.RewriteEventVar(args, EventVar.Label.FIX_DAMAGE, damage);
			Common.RewriteEventVar(args, EventVar.Label.FIX_DAMAGE_FLAG, TRUE);
		}
