		public static void handler_Takuwaeru(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			byte count = bpp.COUNTER_Get(BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU);
			if (count >= 3)
				return;
			count++;

			var counterDesc = new Section_FromEvent_SetCounter.Description();
			counterDesc.pokeID = pokeID;
			counterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU;
			counterDesc.value = count;
			Common.SetPokeCounter(args, counterDesc);

			// 017ff240: the message description's pokeID is not set
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Takuwaeru);
			msgDesc.message.AddArg(pokeID);
			msgDesc.message.AddArg(count);
			Common.Message(args, msgDesc);

			var defDesc = new Section_FromEvent_RankEffect.Description();
			defDesc.pokeID = pokeID;
			defDesc.targetPokeCount = 1;
			defDesc.targetPokeID[0] = pokeID;
			defDesc.rankType = WazaRankEffect.DEFENCE;
			defDesc.rankVolume = 1;
			defDesc.byWazaEffect = true;
			if (Common.RankEffect(args, defDesc))
			{
				var defCounterDesc = new Section_FromEvent_SetCounter.Description();
				defCounterDesc.pokeID = pokeID;
				defCounterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU_DEF;
				defCounterDesc.value = (byte)(bpp.COUNTER_Get(BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU_DEF) + 1);
				Common.SetPokeCounter(args, defCounterDesc);
			}

			var spdefDesc = new Section_FromEvent_RankEffect.Description();
			spdefDesc.pokeID = pokeID;
			spdefDesc.targetPokeCount = 1;
			spdefDesc.targetPokeID[0] = pokeID;
			spdefDesc.rankType = WazaRankEffect.SP_DEFENCE;
			spdefDesc.rankVolume = 1;
			spdefDesc.byWazaEffect = true;
			if (Common.RankEffect(args, spdefDesc))
			{
				var spdefCounterDesc = new Section_FromEvent_SetCounter.Description();
				spdefCounterDesc.pokeID = pokeID;
				spdefCounterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU_SPDEF;
				spdefCounterDesc.value = (byte)(bpp.COUNTER_Get(BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU_SPDEF) + 1);
				Common.SetPokeCounter(args, spdefCounterDesc);
			}
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
