				counterDesc.pokeID = pokeID;
				counterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU_DEF;
				counterDesc.value = 0;
				Common.SetPokeCounter(args, counterDesc);
			}
			if (spdefCount != 0)
			{
				var rankDesc = new Section_FromEvent_RankEffect.Description();
				rankDesc.pokeID = pokeID;
				rankDesc.targetPokeCount = 1;
				rankDesc.targetPokeID[0] = pokeID;
