				counterDesc.pokeID = pokeID;
				counterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU_SPDEF;
				counterDesc.value = 0;
				Common.SetPokeCounter(args, counterDesc);
			}
			if (count != 0)
			{
				var counterDesc = new Section_FromEvent_SetCounter.Description();
				counterDesc.pokeID = pokeID;
				counterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_TAKUWAERU;
				counterDesc.value = 0;
				Common.SetPokeCounter(args, counterDesc);
				var msgDesc = new Section_FromEvent_Message.Description();
				msgDesc.pokeID = pokeID;
				msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TakuwaeOff);
				msgDesc.message.AddArg(pokeID);
				Common.Message(args, msgDesc);
