		public static void common_Counter_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in global::Pml.WazaData.WazaDamageType dmgType, in byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			var rec = new BTL_POKEPARAM.WAZADMG_REC();
			if (!common_Counter_GetRec(args, dmgType, rec, pokeID))
				Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.OTHER);
		}
		public static void common_Counter_SetTarget(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in global::Pml.WazaData.WazaDamageType dmgType, in byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			var rec = new BTL_POKEPARAM.WAZADMG_REC();
			if (!common_Counter_GetRec(args, dmgType, rec, pokeID))
				return;
			byte targetPokeID = rec.pokeID;
			if (Common.GetExistFrontPokePos(args, targetPokeID) == BtlPokePos.POS_NULL)
			{
				// the attacker left the field: whoever now stands at its position, else an automatic target, else the record
				byte existPokeID = PokeID.INVALID;
				if (rec.pokePos != BtlPokePos.POS_NULL)
					existPokeID = Common.GetExistPokeID(args, rec.pokePos);
				if (existPokeID == PokeID.INVALID)
				{
					BtlPokePos autoPos = Common.DecideWazaTargetAuto(args, pokeID, WazaNo.HATAKU);
					if (autoPos != BtlPokePos.POS_NULL)
						existPokeID = Common.GetExistPokeID(args, autoPos);
				}
				targetPokeID = existPokeID != PokeID.INVALID ? existPokeID : rec.pokeID;
			}
			Common.RewriteEventVar(args, EventVar.Label.POKEID_DEF, targetPokeID);
		}
		public static void common_Counter_CalcDamage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in global::Pml.WazaData.WazaDamageType dmgType, in int ratio, in byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			var rec = new BTL_POKEPARAM.WAZADMG_REC();
			if (!common_Counter_GetRec(args, dmgType, rec, pokeID))
				return;
			uint damage = calc.MulRatio(rec.damage, ratio);
			if (damage == 0)
				damage = 1;
			Common.RewriteEventVar(args, EventVar.Label.FIX_DAMAGE, (int)damage);
			Common.RewriteEventVar(args, EventVar.Label.FIX_DAMAGE_FLAG, TRUE);
		}
		public static bool common_Counter_GetRec(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in global::Pml.WazaData.WazaDamageType dmgType, global::Dpr.Battle.Logic.BTL_POKEPARAM.WAZADMG_REC rec, in byte pokeID) {
			// 018006d0: this turn's damage records, newest first; the first one dealt by a non-ally with the wanted damage
			// type (NONE = any) wins
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			for (byte idx = 0; bpp.WAZADMGREC_Get(0, idx, rec); idx++)
			{
				if (args.pMainModule.IsFriendPokeID(pokeID, rec.pokeID))
					continue;
				if (dmgType == WazaDamageType.NONE || rec.damageType == dmgType)
					return true;
			}
			return false;
		}
