		public static void handler_Totteoki(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			// 01800914: WAZA_GetCount() inlined (+0x3c); byte index, byte used-move counter
			byte wazaCount = bpp.WAZA_GetCount();
			if (wazaCount != 0)
			{
				byte usedCount = 0;
				bool hasTotteoki = false;
				for (byte i = 0; i < wazaCount; i++)
				{
					if (bpp.WAZA_GetID(i) == WazaNo.TOTTEOKI)
					{
						hasTotteoki = true;
						continue;
					}
					usedCount += (byte)(bpp.WAZA_CheckUsedInAlive(i) ? 1 : 0);
				}
				if (wazaCount >= 2 && hasTotteoki && wazaCount - 1 <= usedCount)
					return;
			}
			Common.RewriteEventVar_FAIL_CAUSE(args, WazaFailCause.OTHER);
		}
