		public static void handler_Ibiki_CheckFail_2(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			// 01800c00: one shared RewriteEventVar tail with the value chosen per branch
			WazaFailCause cause;
			if ((WazaFailCause)(byte)Common.GetEventVar(args, EventVar.Label.FAIL_CAUSE) == WazaFailCause.NEMURI)
			{
				cause = WazaFailCause.NONE;
			}
			else
			{
				if (bpp.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_INCLUDE_ZETTAINEMURI))
					return;
				cause = WazaFailCause.OTHER;
			}
			Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)cause);
		}
