		public static bool handler_Fuiuti_CheckSuccess(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte targetPokeID) {
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_WAZAPROC_DONE))
				return false;
			PokeAction action = Common.SearchByPokeID(args, targetPokeID, true, true);
			if (action == null)
				return false;
			WazaNo waza = PokeAction.GetWazaID(action);
			if (waza == WazaNo.NULL)
				return false;
			return WAZADATA.IsDamage(waza);
		}
