		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Abareru() {
			return HandlerTable_Abareru;
		}
		public static void handler_Abareru(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetEventVar(args, EventVar.Label.ACTION_DESC_IS_ODORIKO_REACTION) != 0)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.CheckSick(WazaSick.WAZASICK_WAZALOCK))
				return;
			if (Common.GetWorkValue(args, WORKIDX_STICK) != 0 || bpp.IsRaidBoss())
				return;
			byte turns = (byte)(calc.GetRand(2) + 2);
			ushort waza = Common.GetSubID(args);

			var lockDesc = new Section_AddSick.Description();
			lockDesc.sickID = WazaSick.WAZASICK_WAZALOCK;
			lockDesc.sickCont = SICKCONT.MakeTurnParam(pokeID, turns, waza);
			lockDesc.targetPokeID = pokeID;
			lockDesc.pokeID = pokeID;
			Common.AddSick(args, lockDesc);

			var abareDesc = new Section_AddSick.Description();
			abareDesc.sickID = WazaSick.WAZASICK_ABARERU;
			abareDesc.sickCont = SICKCONT.MakeTurnParam(pokeID, turns, waza);
			abareDesc.targetPokeID = pokeID;
			abareDesc.pokeID = pokeID;
			Common.AddSick(args, abareDesc);

			Common.SetWorkValue(args, WORKIDX_STICK, TRUE);
		}
		public static void abareru_Unlock(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID) {
			var lockDesc = new Section_CureSick.Description();
			lockDesc.sick = (WazaSickEx)WazaSick.WAZASICK_WAZALOCK;
			lockDesc.targetPokeCount = 1;
			lockDesc.targetPokeID[0] = pokeID;
			lockDesc.pokeID = pokeID;
			Common.CureSick(args, lockDesc);

			var abareDesc = new Section_CureSick.Description();
			abareDesc.sick = (WazaSickEx)WazaSick.WAZASICK_ABARERU;
			abareDesc.targetPokeCount = 1;
			abareDesc.targetPokeID[0] = pokeID;
			abareDesc.pokeID = pokeID;
			Common.CureSick(args, abareDesc);

			// RemoveForce inlined (its init flag 0x4cbb8e9): GetSubID runs before GetID
			RemoveForce(args.pEventSystem, Common.GetPokeParam(args, pokeID), (WazaNo)Common.GetSubID(args));
		}
		public static void handler_Abareru_SeqEnd(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// 01802720: common_IsMyEvent inlined (direct EVENTVAR_GetValue reads, no flag)
			if (!common_IsMyEvent(args, EventVar.Label.POKEID, pokeID))
				return;
			if (Common.GetEventVar(args, EventVar.Label.ACTION_DESC_IS_ODORIKO_REACTION) != 0)
				return;
			if (Common.GetWorkValue(args, WORKIDX_STICK) == 0)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (Common.GetSubID(args) != Common.GetEventVar(args, EventVar.Label.WAZAID))
				return;
			int genFlag = Common.GetEventVar(args, EventVar.Label.GEN_FLAG);
			if (bpp.IsSickLastTurn(WazaSick.WAZASICK_ABARERU))
			{
				// the rampage ended normally: the user becomes confused
				var desc = new Section_AddSick.Description();
				desc.sickID = WazaSick.WAZASICK_KONRAN;
				calc.MakeDefaultWazaSickCont(WazaSick.WAZASICK_KONRAN, bpp, out desc.sickCont);
				desc.targetPokeID = pokeID;
				desc.pokeID = pokeID;
				desc.isStandardMessageDisable = true;
				desc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.KonranAbare);
				desc.specialMessage.AddArg(pokeID);
				Common.AddSick(args, desc);
			}
			else if (genFlag != 0)
			{
				return;
			}
			abareru_Unlock(args, pokeID);
		}
		public static void handler_Abareru_turnCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetWorkValue(args, WORKIDX_STICK) == 0)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_ONLY_SICK) && bpp.CheckSick(WazaSick.WAZASICK_ABARERU))
				return;
			abareru_Unlock(args, pokeID);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Sawagu() {
			return HandlerTable_Sawagu;
		}
		public static void handler_Sawagu(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// 01802b90: common_IsMyEvent inlined (POKEID_ATK)
			if (!common_IsMyEvent(args, EventVar.Label.POKEID_ATK, pokeID))
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.CheckSick(WazaSick.WAZASICK_WAZALOCK))
				return;
			if (Common.GetWorkValue(args, WORKIDX_STICK) != 0 || bpp.IsRaidBoss())
				return;

			var lockDesc = new Section_AddSick.Description();
			lockDesc.pokeID = pokeID;
			lockDesc.sickID = WazaSick.WAZASICK_WAZALOCK;
			lockDesc.sickCont = SICKCONT.MakeTurnParam(pokeID, 3, Common.GetSubID(args));
			lockDesc.isFailResultDisplay = false;
			lockDesc.targetPokeID = pokeID;
			Common.AddSick(args, lockDesc);

			var sawaguDesc = new Section_AddSick.Description();
			sawaguDesc.pokeID = pokeID;
			sawaguDesc.sickID = WazaSick.WAZASICK_SAWAGU;
			sawaguDesc.sickCont = SICKCONT.MakeTurnParam(pokeID, 3, Common.GetSubID(args));
			sawaguDesc.isFailResultDisplay = false;
			sawaguDesc.targetPokeID = pokeID;
			Common.AddSick(args, sawaguDesc);

			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Sawagu);
			msgDesc.message.AddArg(pokeID);
			Common.Message(args, msgDesc);

			// wake every sleeping Pokémon on the field
			byte[] pokeIDs = new byte[6];
			var exPos = new ExPokePos(ExPokePos.ExPosType.FULL_ALL, Common.GetExistFrontPokePos(args, pokeID));
			byte count = Common.ExpandExistPokeID(args, exPos, pokeIDs);
			for (int i = 0; i < count; i++)
			{
				BTL_POKEPARAM target = Common.GetPokeParam(args, pokeIDs[i]);
				if (!target.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_ONLY_SICK))
					continue;
				var cureDesc = new Section_CureSick.Description();
				cureDesc.pokeID = pokeID;
				cureDesc.sick = (WazaSickEx)WazaSick.WAZASICK_NEMURI;
				cureDesc.targetPokeCount = 1;
				cureDesc.targetPokeID[0] = pokeIDs[i];
				cureDesc.successSpMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SawaguWake);
				cureDesc.successSpMessage.AddArg(pokeIDs[i]);
				Common.CureSick(args, cureDesc);
			}
			Common.SetWorkValue(args, WORKIDX_STICK, TRUE);
		}
		public static void Sawagu_CureLock(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			var lockDesc = new Section_CureSick.Description();
