		}
		public static void handler_Sawagu_turnCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetWorkValue(args, WORKIDX_STICK) == 0)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.IsDead())
				return;
			if (bpp.CheckSick(WazaSick.WAZASICK_ZIGOKUDUKI))
				Sawagu_CureLock(args, pokeID);
			bool isLocked = bpp.CheckSick(WazaSick.WAZASICK_WAZALOCK);
			var msgDesc = new Section_FromEvent_Message.Description();
			if (isLocked)
			{
				msgDesc.pokeID = pokeID;
				msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SawaguCont);
				msgDesc.message.AddArg(pokeID);
				Common.Message(args, msgDesc);
			}
			else
			{
				msgDesc.pokeID = pokeID;
				msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SawaguCure);
				msgDesc.message.AddArg(pokeID);
				Common.Message(args, msgDesc);
				// RemoveForce inlined (its init flag 0x4cbb8e9)
				RemoveForce(args.pEventSystem, bpp, (WazaNo)Common.GetSubID(args));
			}
		}
		public static void handler_Sawagu_CheckSickFail(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetWorkValue(args, WORKIDX_STICK) == 0)
