			ushort strID = (ushort)(defPokeID == pokeID ? BTL_STRID_SET.SawaguSleeplessSelf : BTL_STRID_SET.SawaguSleepless);
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, strID);
			desc.message.AddArg(defPokeID);
			Common.Message(args, desc);
		}
