		public static void handler_Korogaru_Pow(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			int count = Common.GetWorkValue(args, 0);
			// 01803e00: ratio doubled once per earlier hit (the loop is unrolled ×4), and again after Defense Curl (`lsl` by the flag)
			int ratio = 1;
			for (int i = 0; i < count; i++)
				ratio *= 2;
			if (bpp.CONTFLAG_Get(ContFlag.CONTFLG_MARUKUNARU))
				ratio *= 2;
			Common.MulWazaBasePower(args, (uint)ratio);
			Common.SetWorkValue(args, 0, count + 1);
			if (Common.GetWorkValue(args, 1) <= count + 1)
				removeHandlerForce(args.pEventSystem, pokeID, (WazaNo)Common.GetSubID(args));
		}
