		public static void handler_GyroBall(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte defPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			uint atkAgility = common_CalcAgility(args, pokeID);
			uint defAgility = common_CalcAgility(args, defPokeID);
			// 0180437c: unguarded `udiv` (ARM64 yields 0 for a zero divisor); capped at 149, then +1
			uint pow = atkAgility != 0 ? defAgility * 25 / atkAgility : 0;
			if (pow > 149)
				pow = 149;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, (int)(pow + 1));
		}
		public static ushort common_CalcAgility(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			var desc = new Section_FromEvent_CalcAgility.Description();
			desc.poke = Common.GetPokeParam(args, pokeID);
			desc.isTrickRoomApply = false;
			return Common.CalcAgility(args, desc);
		}
