		public static void handler_Revenge(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			byte defPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			var rec = new BTL_POKEPARAM.WAZADMG_REC();
			// this turn's records: the first one from the target that dealt damage doubles the power
			for (byte idx = 0; bpp.WAZADMGREC_Get(0, idx, rec); idx++)
			{
				if (rec.pokeID == defPokeID && rec.damage != 0)
				{
					Common.MulWazaBasePower(args, 2);
					return;
				}
			}
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Jitabata() {
			return HandlerTable_Jitabata;
		}
		public static void handler_Jitabata(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			handler_JitabataTableElem[] table = handler_JitabataTable;
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			int hp = bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
			int maxHP = bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP);
			// 018047f4: 64-bit multiply + unguarded `sdiv` (ARM64 yields 0 for a zero divisor); 0 -> 1; unsigned table compare
			uint ratio = maxHP != 0 ? (uint)((long)hp * 48 / maxHP) : 0;
			if (ratio == 0)
				ratio = 1;
			int i;
			for (i = 0; i < table.Length - 1; i++)
			{
				if (ratio <= table[i].dot_ratio)
					break;
			}
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, table[i].pow);
		}
