		public static void handler_Funka(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			int hp = bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
			uint maxHP = (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP);
			uint product = (ushort)WAZADATA.GetPower((WazaNo)Common.GetSubID(args)) * (uint)hp;
			// 01804dc8: unguarded `udiv`; a product below max HP gives 1 (`csinc ls`)
			uint pow = maxHP != 0 ? product / maxHP : 0;
			if (product < maxHP)
				pow = 1;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, (int)pow);
		}
