		public static void handler_Siomizu(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF));
			// 01805114: `cmp #0x32, lsl #12 ; b.gt` = HP ratio (FX32) <= 50 %
			if (target.GetHPRatio() <= (50 << 12))
				Common.MulEventVar(args, EventVar.Label.WAZA_POWER_RATIO, 0x2000);
		}
