		public static void handler_RenzokuGiri(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if ((ushort)bpp.GetPrevWazaID() != Common.GetSubID(args))
				return;
			uint pow = (uint)Common.GetEventVar(args, EventVar.Label.WAZA_POWER);
			uint contCount = bpp.GetWazaContCounter();
			for (uint i = 0; i < contCount; i++)
			{
				pow *= 2;
				if (pow > 160)
				{
					pow = 160;
					break;
				}
			}
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, (int)pow);
		}
