		public static void handler_Ketaguri(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			var desc = new Section_FromEvent_GetWeight.Description();
			desc.pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			uint weight = Common.GetWeight(args, desc);
			int pow;
			if (weight >= 2000)
				pow = 120;
			else if (weight >= 1000)
				pow = 100;
			else if (weight >= 500)
				pow = 80;
			else if (weight >= 250)
				pow = 60;
			else if (weight >= 100)
				pow = 40;
			else
				pow = 20;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, pow);
		}
