		private static bool get_WeatherBallParam(ref global::Dpr.Battle.Logic.Handler.Waza.WeatherBallParam param, global::Dpr.Battle.Logic.BtlWeather weather) {
			switch (weather)
			{
				case BtlWeather.BTL_WEATHER_SHINE: param.type = PokeType.HONOO; param.effIndex = 1; return true;
				case BtlWeather.BTL_WEATHER_RAIN: param.type = PokeType.MIZU; param.effIndex = 2; return true;
				case BtlWeather.BTL_WEATHER_SNOW: param.type = PokeType.KOORI; param.effIndex = 4; return true;
				case BtlWeather.BTL_WEATHER_SAND: param.type = PokeType.IWA; param.effIndex = 3; return true;
				case BtlWeather.BTL_WEATHER_STORM: param.type = PokeType.MIZU; param.effIndex = 2; return true;
				case BtlWeather.BTL_WEATHER_DAY: param.type = PokeType.HONOO; param.effIndex = 1; return true;
				default: param.type = PokeType.NORMAL; param.effIndex = 0; return false;
			}
		}
		public static void handler_WeatherBall_Type(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BtlWeather weather = Common.GetLocalWeather(args, pokeID);
			// 01805830: WAZA_TYPE is read into the param before the (inlined) get_WeatherBallParam overwrites both fields
			WeatherBallParam param;
			param.type = (PokeType)Common.GetEventVar(args, EventVar.Label.WAZA_TYPE);
			param.effIndex = 0;
			get_WeatherBallParam(ref param, weather);
			Common.RewriteEventVar(args, EventVar.Label.WAZA_TYPE, (int)param.type);
			var desc = new Section_FromEvent_SetWazaEffectIndex.Description();
			desc.effectIndex = param.effIndex;
			Common.SetWazaEffectIndex(args, desc);
		}
		public static void handler_WeatherBall_Pow(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.GetLocalWeather(args, pokeID) == BtlWeather.BTL_WEATHER_NONE)
				return;
			if (Common.GetLocalWeather(args, pokeID) == BtlWeather.BTL_WEATHER_TURBULENCE)
				return;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, Common.GetEventVar(args, EventVar.Label.WAZA_POWER) * 2);
		}
		public static void handler_WeatherBall_ChangeGWaza(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetEventVar(args, EventVar.Label.ORG_WAZAID) != Common.GetSubID(args))
				return;
			BtlWeather weather = Common.GetLocalWeather(args, pokeID);
			// get_WeatherBallParam inlined (Waza class-init test + the same shift table)
			WeatherBallParam param = default;
			get_WeatherBallParam(ref param, weather);
			Common.RewriteEventVar(args, EventVar.Label.WAZAID, (int)GWaza.GetGWaza(param.type));
		}
