		public static void technoBaster_GetParam(ref global::Pml.PokeType pType, ref byte pEffectIdx, global::Pml.ItemNo item) {
			// 01806db0: only the four drives write the outputs (type from the packed table 0x0e090c0a, index = item − 0x73)
			switch (item)
			{
				case ItemNo.AKUAKASETTO:
					pType = PokeType.MIZU;
					pEffectIdx = 1;
					break;
				case ItemNo.INAZUMAKASETTO:
					pType = PokeType.DENKI;
					pEffectIdx = 2;
					break;
				case ItemNo.BUREIZUKASETTO:
					pType = PokeType.HONOO;
					pEffectIdx = 3;
					break;
				case ItemNo.HURIIZUKASETTO:
					pType = PokeType.KOORI;
					pEffectIdx = 4;
					break;
			}
		}
		public static void handler_TechnoBaster(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int eventPokeID = Common.GetEventVar(args, EventVar.Label.POKEID);
			if (eventPokeID != pokeID)
				return;
			// 01806e94: POKEID is read a second time and compared with the first value (as shipped)
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != eventPokeID)
				return;
			if (!Common.CheckItemUsable(args, pokeID))
				return;
			ushort item = Common.GetPokeParam(args, pokeID).GetItem();
			// technoBaster_GetParam and common_SetWazaEffectIndex (flag 0x4cbb8eb) inlined
			PokeType type = PokeType.NORMAL;
			byte effectIdx = 0;
			technoBaster_GetParam(ref type, ref effectIdx, (ItemNo)item);
			Common.RewriteEventVar(args, EventVar.Label.WAZA_TYPE, (int)type);
			common_SetWazaEffectIndex(args, effectIdx);
		}
