		public static void handler_MagicCoat_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// 018076a0: POKEID compared as a byte
			byte eventPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if (eventPokeID == pokeID)
			{
				// the user moves last: Magic Coat fails
				if (Common.CheckPokeOrderLast(args, pokeID) && Common.GetEventVar(args, EventVar.Label.WAZAID) == Common.GetSubID(args))
					Common.RewriteEventVar_FAIL_CAUSE(args, WazaFailCause.OTHER);
			}
			else if (!Common.IsFriendPokeID(args, pokeID, eventPokeID))
			{
				Common.MagicCoat_CheckSideEffWaza(args, pokeID);
			}
		}
