		public static void handler_Trick(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.CheckCantStealWildPoke(args, pokeID))
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			ushort userItem = user.GetItem();
			ushort targetItem = target.GetItem();
			if (userItem == (ushort)ItemNo.DUMMY_DATA && targetItem == (ushort)ItemNo.DUMMY_DATA)
				return;
			ushort userMonsNo = user.GetMonsNo();
			ushort targetMonsNo = target.GetMonsNo();
			if (calc.ITEM_IsMail(userItem) || calc.ITEM_IsMail(targetItem))
				return;
			if (Common.CheckUnbreakablePokeItem(userMonsNo, targetItem) || Common.CheckUnbreakablePokeItem(targetMonsNo, userItem) ||
				Common.CheckUnbreakablePokeItem(userMonsNo, userItem) || Common.CheckUnbreakablePokeItem(targetMonsNo, targetItem))
				return;
			var desc = new Section_FromEvent_SwapItem.Description();
			desc.userPokeID = pokeID;
			desc.targetPokeID = targetPokeID;
			desc.isIncRecordCount_StealItemFromWildPoke = true;
			desc.successMessage1.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Trick);
			desc.successMessage1.AddArg(pokeID);
			if (targetItem != (ushort)ItemNo.DUMMY_DATA)
			{
				desc.successMessage3.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TrickGetItem);
				desc.successMessage3.AddArg(pokeID);
				desc.successMessage3.AddArg(targetItem);
			}
			if (userItem != (ushort)ItemNo.DUMMY_DATA)
			{
				desc.successMessage2.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TrickGetItem);
				desc.successMessage2.AddArg(targetPokeID);
				desc.successMessage2.AddArg(userItem);
			}
			Common.SwapItem(args, desc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
