		public static void handler_Mamoru_StartSeq(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.WAZAID) != Common.GetSubID(args))
				return;
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// 018090f8: the table is read before GetPokeParam; the counter survives only when the previous move was a protect move
			ushort[] table = WazaTable_Mamoru;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			for (int i = 0; i < table.Length; i++)
			{
				if (table[i] == (ushort)bpp.GetPrevWazaID())
					return;
			}
			var desc = new Section_FromEvent_SetCounter.Description();
			desc.pokeID = pokeID;
			desc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_MAMORU;
			desc.value = 0;
			Common.SetPokeCounter(args, desc);
		}
		public static void handler_Mamoru_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.WAZAID) != Common.GetSubID(args))
				return;
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			ushort[] table = RandRangeTable_Mamoru;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			byte counter = bpp.COUNTER_Get(BTL_POKEPARAM.Counter.COUNTER_MAMORU);
			// consecutive use succeeds with 1 / RandRangeTable_Mamoru[min(counter, Length - 1)]; last to move also fails
			// (one shared RewriteEventVar site @01809390)
			bool fail = false;
			if (counter != 0)
			{
				int idx = counter < table.Length ? counter : table.Length - 1;
				fail = calc.GetRand(table[idx]) != 0;
			}
			if (fail || Common.CheckPokeOrderLast(args, pokeID))
				Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.OTHER);
		}
		public static void handler_Mamoru_ExeFail(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.WAZAID) != Common.GetSubID(args))
				return;
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			var desc = new Section_FromEvent_SetCounter.Description();
			desc.pokeID = pokeID;
			desc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_MAMORU;
			desc.value = 0;
			Common.SetPokeCounter(args, desc);
			Common.RemoveFactor(args);
		}
		public static bool handler_Mamoru_Core(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return false;
			var flagDesc = new Section_FromEvent_SetTurnFlag.Description();
			flagDesc.pokeID = pokeID;
			flagDesc.flag = BTL_POKEPARAM.TurnFlag.TURNFLG_MAMORU;
			Common.SetTurnFlag(args, flagDesc);
			IncrementMamoruCounter(args, pokeID);
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.MamoruReady);
			msgDesc.message.AddArg(pokeID);
			Common.Message(args, msgDesc);
			return true;
		}
		public static void IncrementMamoruCounter(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID) {
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			var desc = new Section_FromEvent_SetCounter.Description();
			desc.pokeID = pokeID;
			desc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_MAMORU;
			desc.value = (byte)(bpp.COUNTER_Get(BTL_POKEPARAM.Counter.COUNTER_MAMORU) + 1);
			Common.SetPokeCounter(args, desc);
		}
