			if (handler_Mamoru_Core(args, pokeID))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
			Common.SetWorkValue(args, WORKIDX_STICK, TRUE);
		}
		public static bool mamoru_MsgAfterCritical(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
