				return false;
			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.protectpierce);
			desc.message.AddArg(pokeID);
