		public static void handler_Mamoru_Dmg(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;
			// a protect-piercing hit (G-move) deals 1/4 and flags the follow-up message
			if (!Common.GetPokeParam(args, pokeID).TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_MAMORU))
				return;
			if (Common.RewriteEventVar(args, EventVar.Label.RATIO_EX, 0x400))
				Common.SetWorkValue(args, 0, 1);
		}
