		}
		public static void handler_PsycoShift(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			Pml.PokePara.Sick sick = bpp.GetPokeSick();
			if (sick == Pml.PokePara.Sick.NONE)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (target.GetPokeSick() != Pml.PokePara.Sick.NONE)
				return;
			// bad poison is handed over as bad poison (counter restarted), anything else as a default condition
			BTL_SICKCONT cont = bpp.GetSickCont((WazaSick)sick);
			if (sick == Pml.PokePara.Sick.DOKU && SICKCONT.IsMoudokuCont(cont))
				cont = SICKCONT.MakeMoudokuCont(pokeID);
			else
				cont = calc.MakeDefaultPokeSickCont(sick, pokeID, false);
			var addDesc = new Section_AddSick.Description();
			addDesc.pokeID = pokeID;
			addDesc.sickID = (WazaSick)sick;
			addDesc.sickCont = cont;
			addDesc.targetPokeID = targetPokeID;
			addDesc.isFailResultDisplay = true;
			bool result = Common.AddSick(args, addDesc);
			if (result)
			{
				var cureDesc = new Section_CureSick.Description();
				cureDesc.targetPokeCount = 1;
				cureDesc.pokeID = pokeID;
				cureDesc.sick = (WazaSickEx)sick;
				cureDesc.targetPokeID[0] = pokeID;
				Common.CureSick(args, cureDesc);
			}
			Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, FALSE);
			if (result)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
