		public static void handler_Itamiwake(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			// 0180a20c: Waza class-init test + the same formula = inlined itamiwake_CalcShiftHP
			itamiwake_CalcShiftHP(out int attackerHP, out int targetHP, attacker, target);
			var hpDesc = new Section_FromEvent_ShiftHP.Description();
			hpDesc.targetPokeCount = 2;
			hpDesc.pokeID = pokeID;
			hpDesc.targetPokeID[0] = pokeID;
			hpDesc.volume[0] = attackerHP;
			hpDesc.targetPokeID[1] = targetPokeID;
			hpDesc.volume[1] = targetHP;
			hpDesc.isItemReactionDisable = true;
			hpDesc.damageCause = DamageCause.ITAMIWAKE;
			Common.ShiftHP(args, hpDesc);
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Itamiwake);
			Common.Message(args, msgDesc);
			var reactDesc = new Section_CheckItemReaction.Description();
			reactDesc.pokeID = pokeID;
			reactDesc.reactionType = 1;
			Common.CheckItemReaction(args, reactDesc);
			var reactDesc2 = new Section_CheckItemReaction.Description();
			reactDesc2.pokeID = targetPokeID;
			reactDesc2.reactionType = 1;
			Common.CheckItemReaction(args, reactDesc2);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
		public static void itamiwake_CalcShiftHP(out int pAttackerHP, out int pDefenderHP, global::Dpr.Battle.Logic.BTL_POKEPARAM pAttacker, global::Dpr.Battle.Logic.BTL_POKEPARAM pDefender) {
			int attackerHP = pAttacker.GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G);
			int defenderHP = pDefender.GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G);
			// 0180a434: the average is an UNSIGNED halving (`lsr #1`)
			int average = (int)((uint)(attackerHP + defenderHP) >> 1);
			pAttackerHP = average - attackerHP;
			pDefenderHP = average - defenderHP;
		}
