		public static void SleepGuardSideEffects(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, bool wakeFlag) {
			// 0180a9e8: `cbz count` + an equality loop = unsigned count; getEventVarTarget inlined (flag 0x4cbb8ea)
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			for (int i = 0; i < targetCount; i++)
			{
				// SleepGuardSideEffect ignores attackPokeId (the binary leaves w1 stale) — natural argument written
				SleepGuardSideEffect(args, pokeID, getEventVarTarget(args, i), wakeFlag);
			}
		}
		public static void SleepGuardSideEffect(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte attackPokeId, byte targetPokeId, bool wakeFlag) {
			var desc = new Section_SideEffect_Sleep.Description();
			desc.side = Common.PokeIDtoSide(args, targetPokeId);
			desc.wakeUpFlag = wakeFlag;
			calc.BITFLG_Construction(desc.flags);
			for (int eff = (int)BtlSideEffect.BTL_SIDEEFF_START; eff < (int)BtlSideEffect.BTL_SIDEEFF_MAX; eff++)
			{
				if (tables.IsGuardTypeSideEffect((BtlSideEffect)eff))
					calc.BITFLG_Set(desc.flags, (uint)eff);
			}
			Common.SleepSideEffect(args, desc);
		}
