		public static void common_feint_proc(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, ushort strID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			bool isGuardSideEffect = common_IsExistGuardTypeSideEffect(args, targetPokeID, true);
			bool isMamoru = target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_MAMORU);
			if (isGuardSideEffect || isMamoru)
				common_mamoruBreakAfter(args, pokeID, target, strID);
