		public static void common_mamoruBreakAfter(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte attackPokeID, global::Dpr.Battle.Logic.BTL_POKEPARAM target, ushort strID) {
			byte targetPokeID = target.GetID();
			bool isGuardSideEffect = common_IsExistGuardTypeSideEffect(args, targetPokeID, false);
			bool isMamoru = target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_MAMORU);
			if (isGuardSideEffect || isMamoru)
			{
				var flagDesc = new Section_FromEvent_ResetTurnFlag.Description();
				flagDesc.pokeID = targetPokeID;
				flagDesc.flag = BTL_POKEPARAM.TurnFlag.TURNFLG_MAMORU;
				Common.ResetTurnFlag(args, flagDesc);
				var counterDesc = new Section_FromEvent_SetCounter.Description();
				counterDesc.pokeID = targetPokeID;
				counterDesc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_MAMORU;
				counterDesc.value = 0;
				Common.SetPokeCounter(args, counterDesc);
			}
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = attackPokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, strID);
			msgDesc.message.AddArg(targetPokeID);
			Common.Message(args, msgDesc);
			common_mamoruBreak_RemoveSideEff(args, attackPokeID, target);
		}
		public static void common_mamoruBreak_RemoveSideEff(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BTL_POKEPARAM target) {
			var desc = new Section_SideEffect_Remove.Description();
			desc.pokeID = pokeID;
			byte targetPokeID = target.GetID();
			desc.side = Common.PokeIDtoSide(args, targetPokeID);
			calc.BITFLG_Construction(desc.flags);
			for (int eff = (int)BtlSideEffect.BTL_SIDEEFF_START; eff < (int)BtlSideEffect.BTL_SIDEEFF_MAX; eff++)
			{
				if (tables.IsGuardTypeSideEffect((BtlSideEffect)eff))
					calc.BITFLG_Set(desc.flags, (uint)eff);
			}
			Common.RemoveSideEffect(args, desc);
		}
		public static bool common_IsExistGuardTypeSideEffect(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte targetPokeID, bool bIncludeNotCountupType) {
			BtlSide side = Common.PokeIDtoSide(args, targetPokeID);
			if (bIncludeNotCountupType)
			{
				for (int eff = (int)BtlSideEffect.BTL_SIDEEFF_START; eff < (int)BtlSideEffect.BTL_SIDEEFF_MAX; eff++)
				{
					if (Side.IsExist(args.pEventSystem, side, (BtlSideEffect)eff) && tables.IsGuardTypeSideEffect((BtlSideEffect)eff))
						return true;
				}
			}
			else
			{
				// 0180b058: Crafty Shield (TRICKGUARD) does not count here
				for (int eff = (int)BtlSideEffect.BTL_SIDEEFF_START; eff < (int)BtlSideEffect.BTL_SIDEEFF_MAX; eff++)
				{
					if (Side.IsExist(args.pEventSystem, side, (BtlSideEffect)eff) && tables.IsGuardTypeSideEffect((BtlSideEffect)eff) &&
						(BtlSideEffect)eff != BtlSideEffect.BTL_SIDEEFF_TRICKGUARD)
						return true;
				}
			}
			return false;
		}
