		}
		public static void handler_TuboWoTuku(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// InitializeArray @ global-metadata 0x669005 = {1, 2, 5, 3, 4, 6, 7}
			BTL_POKEPARAM.ValueID[] rankTypes = new BTL_POKEPARAM.ValueID[]
			{
				BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK, BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK, BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK,
				BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK, BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK, BTL_POKEPARAM.ValueID.BPP_HIT_RATIO,
				BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO,
			};
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			// byte counters throughout (`uxtb` compares, `tst #0xff`)
			byte validCount = 0;
			for (byte i = 0; i < rankTypes.Length; i++)
				validCount += (byte)(target.IsRankEffectValid(rankTypes[i], 2) ? 1 : 0);
			if (validCount == 0)
				return;
			byte pick = (byte)calc.GetRand(validCount);
			for (byte i = 0; i < rankTypes.Length; i++)
			{
				if (!target.IsRankEffectValid(rankTypes[i], 2))
					continue;
				if (pick != 0)
				{
					pick--;
					continue;
				}
				var desc = new Section_FromEvent_RankEffect.Description();
				desc.pokeID = pokeID;
				desc.targetPokeID[0] = targetPokeID;
				desc.targetPokeCount = 1;
				desc.rankType = (WazaRankEffect)rankTypes[i];
				desc.rankVolume = 2;
				desc.isSpFailMessageDisplay = false;
				desc.byWazaEffect = true;
				desc.isMigawariThrew = true;
				if (Common.RankEffect(args, desc))
					Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
				return;
			}
		}
