		}
		public static void handler_Nemuru_exeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if ((WazaFailCause)(byte)Common.GetEventVar(args, EventVar.Label.FAIL_CAUSE) != WazaFailCause.NONE)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			// one shared RewriteEventVar(FAIL_CAUSE) site with the cause chosen per branch
			WazaFailCause cause;
			if (bpp.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_INCLUDE_ZETTAINEMURI))
				cause = WazaFailCause.OTHER;
			else if (bpp.CheckSick(WazaSick.WAZASICK_KAIHUKUHUUJI))
				cause = WazaFailCause.KAIHUKUHUUJI;
			else if (bpp.IsHPFull())
				cause = WazaFailCause.HPFULL;
			else
			{
				ushort tokusei = (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE);
				if (tokusei != (ushort)TokuseiNo.YARUKI && tokusei != (ushort)TokuseiNo.HUMIN)
					return;
				cause = WazaFailCause.FUMIN;
			}
			Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)cause);
		}
