			sickDesc.sickID = WazaSick.WAZASICK_NEMURI;
			sickDesc.sickCont = SICKCONT.MakeTurn(pokeID, 3);
			sickDesc.isFailResultDisplay = true;
			sickDesc.overWriteMode = SickOverWriteMode.POKESICK;
			sickDesc.isItemReactionDisable = true;
			sickDesc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Nemuru);
			sickDesc.specialMessage.AddArg(pokeID);
			bool result = Common.AddSick(args, sickDesc);
			Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, FALSE);
			if (!result)
				return;
			var recoverDesc = new Section_RecoverHP.Description();
