			recoverDesc.targetPokeID = pokeID;
			recoverDesc.recoverHP = (ushort)(bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP_BEFORE_G) - bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP_BEFORE_G));
			recoverDesc.isSkipFailCheckSP = false;
