		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Texture2() {
			return HandlerTable_Texture2;
		}
		public static void handler_Texture2(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1));
			byte prevType = target.GetPrevWazaType();
			if (prevType == (byte)PokeType.NULL)
				return;
			byte[] types = new byte[18];
			uint count = calc.GetResistTypes((PokeType)prevType, types);
			if (count == 0)
				return;
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			// 0180c0f0: drop the types the user already has (Array.Copy long overload, index kept after a removal)
			long idx = 0;
			while (idx < count)
			{
				if (user.IsMatchType(types[idx]))
				{
					int rest = (int)count - (int)idx - 1;
					if (rest > 0)
						Array.Copy(types, idx + 1, types, idx, rest);
					count--;
				}
				else
				{
					idx++;
				}
			}
			if (count == 0)
				return;
			byte type = types[calc.GetRand(count)];
			var desc = new Section_FromEvent_ChangePokeType.Description();
			desc.pokeID = pokeID;
			desc.nextType = PokeTypePair.MakePure(type);
			desc.exTypeCause = BTL_POKEPARAM.ExTypeCause.EXTYPE_CAUSE_NONE;
			if (Common.ChangeType(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
