		public static void handler_Encore(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			WazaNo waza = target.GetPrevOrgWazaID();
			if (target.CheckSick(WazaSick.WAZASICK_ENCORE))
				return;
			if (tables.IsMatchEncoreFail(waza) || target.WAZA_GetPP_ByNumber(waza) == 0 || target.IsGMode())
				return;
			// one turn longer when the target has already moved this turn
			bool actionDone = target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_ACTION_DONE);
			var desc = new Section_AddSick.Description();
			byte turns = (byte)(actionDone ? 4 : 3);
			desc.pokeID = pokeID;
			desc.sickID = WazaSick.WAZASICK_ENCORE;
			desc.sickCont = SICKCONT.MakeTurnParam(pokeID, turns, (ushort)waza);
			desc.targetPokeID = targetPokeID;
			desc.isFailResultDisplay = false;
			desc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Encore);
			desc.specialMessage.AddArg(targetPokeID);
			if (Common.AddSick(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
