		public static void handler_Kanasibari(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (target.CheckSick(WazaSick.WAZASICK_KANASIBARI))
				return;
			if (GWaza.IsGWaza(target.GetPrevWazaID()))
				return;
			WazaNo waza = target.GetPrevOrgWazaID();
			if (waza == WazaNo.NULL || waza == WazaNo.WARUAGAKI || !target.WAZA_IsUsable(waza))
				return;
			bool actionDone = target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_ACTION_DONE);
			var desc = new Section_AddSick.Description();
			byte turns = (byte)(actionDone ? 5 : 4);
			desc.sickID = WazaSick.WAZASICK_KANASIBARI;
			desc.sickCont = SICKCONT.MakeTurnParam(pokeID, turns, (ushort)waza);
			desc.targetPokeID = targetPokeID;
			desc.pokeID = pokeID;
			if (Common.AddSick(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
		public static global::Pml.WazaNo kanashibari_GetTargetWaza(global::Dpr.Battle.Logic.BTL_POKEPARAM target) {
			// 0180c9c0: GWaza.IsGWaza(prev act) evaluated and discarded; the last SELECTED move is returned (as shipped)
			GWaza.IsGWaza(target.GetPrevWazaID());
			return target.GetPrevOrgWazaID();
		}
