		public static void handler_Present_Check(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// 20 %: the present heals (GEN_FLAG rewrite result kept in work[0] and used as the effect index)
			bool isRecover = false;
			if (calc.IsOccurPer(20))
				isRecover = Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, TRUE);
			Common.SetWorkValue(args, 0, isRecover ? 1 : 0);
			// common_SetWazaEffectIndex inlined (flag 0x4cbb8eb)
			common_SetWazaEffectIndex(args, (byte)(isRecover ? 1 : 0));
		}
		public static void handler_Present_Fix(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.GetWorkValue(args, 0) == 0)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (target.IsHPFull())
			{
				var msgDesc = new Section_FromEvent_Message.Description();
				msgDesc.pokeID = pokeID;
				msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NoEffect);
				msgDesc.message.AddArg(targetPokeID);
				Common.Message(args, msgDesc);
			}
			else
			{
				var recoverDesc = new Section_RecoverHP.Description();
				recoverDesc.userPokeID = pokeID;
				recoverDesc.targetPokeID = targetPokeID;
				recoverDesc.recoverHP = (ushort)calc.QuotMaxHP(target, 4, true);
				recoverDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.HP_Recover);
				recoverDesc.successMessage.AddArg(targetPokeID);
				Common.RecoverHP(args, recoverDesc);
			}
		}
		public static void handler_Present_Pow(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			uint rand = calc.GetRand(80);
			int pow;
			if (rand < 40)
				pow = 40;
			else if (rand < 70)
				pow = 80;
			else
				pow = 120;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, pow);
		}
