		public static bool common_CureFriendPokeSick(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte attackerID, bool excludeOutOfWazaTarget, bool canWriteGenFlag) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != attackerID)
				return false;

			// the parties of every existing client on the attacker's team (byte client counter 0..4)
			BTL_PARTY[] parties = Arrays.InitializeWithDefaultInstances<BTL_PARTY>(5);
			byte myClientID = MainModule.PokeIDtoClientID(attackerID);
			int partyCount = 0;
			for (byte clientID = 0; clientID < 5; clientID++)
			{
				if (!Common.IsClientExist(args, (BTL_CLIENT_ID)clientID))
					continue;
				if (!Common.IsClientFriends(args, (BTL_CLIENT_ID)myClientID, (BTL_CLIENT_ID)clientID))
					continue;
				parties[partyCount++] = Common.GetPartyData(args, (BTL_CLIENT_ID)clientID);
			}

			byte[] targets = new byte[30];
			uint targetCount = 0;
			for (int p = 0; p < partyCount; p++)
			{
				// 0180d590: GetMemberCount() inlined (+0x18); members on the field count only when they are move targets
				byte memberCount = parties[p].GetMemberCount();
				for (byte m = 0; m < memberCount; m++)
				{
					byte pokeID = parties[p].GetMemberDataConst(m).GetID();
					if (excludeOutOfWazaTarget && Common.GetExistFrontPokePos(args, pokeID) != BtlPokePos.POS_NULL && !Common.CheckTargetPokeID(args, pokeID))
						continue;
					if (Common.CheckPokeSick(args, pokeID) != Pml.PokePara.Sick.NONE)
						targets[targetCount++] = pokeID;
				}
			}

			if (targetCount == 0)
			{
				if (canWriteGenFlag)
					Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, TRUE);
				return false;
			}
			var desc = new Section_CureSick.Description();
			desc.pokeID = attackerID;
			desc.sick = WazaSickEx.POKEFULL;
			desc.targetPokeCount = (byte)targetCount;
			for (int i = 0; i < targetCount; i++)
				desc.targetPokeID[i] = targets[i];
			return Common.CureSick(args, desc);
		}
