		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Urami() {
			return HandlerTable_Urami;
		}
		public static void handler_Urami(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			WazaNo waza = target.GetPrevOrgWazaID();
			byte wazaIdx = target.WAZA_SearchIdx(waza);
			if (wazaIdx == BattleDefConst.PTL_WAZA_MAX)
				return;
			byte volume = (byte)target.WAZA_GetPP(wazaIdx);
			if (volume > 4)
				volume = 4;
			if (volume == 0)
				return;
			var desc = new Section_FromEvent_DecrementPP.Description();
			desc.pokeID = targetPokeID;
			desc.volume = volume;
			desc.wazaIdx = wazaIdx;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Urami);
			desc.successMessage.AddArg(targetPokeID);
			desc.successMessage.AddArg((int)waza);
			desc.successMessage.AddArg(volume);
			if (Common.DecrementPP(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_JikoAnji() {
			return HandlerTable_JikoAnji;
		}
		public static void handler_JikoAnji(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			var rankDesc = new Section_FromEvent_RankSet.Description();
			rankDesc.pokeID = pokeID;
			rankDesc.attack = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK);
			rankDesc.defence = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK);
			rankDesc.sp_attack = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK);
			rankDesc.sp_defence = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK);
			rankDesc.agility = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK);
			rankDesc.hit_ratio = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_HIT_RATIO);
			rankDesc.avoid_ratio = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO);
			// 0180e210: GetCriticalRankPure() inlined (+0x3f)
			rankDesc.critical_rank = target.GetCriticalRankPure();
			Common.RankSet(args, rankDesc);
			// Focus Energy and Laser Focus are copied too
			if (target.CONTFLAG_Get(ContFlag.CONTFLG_KIAIDAME))
			{
				var setDesc = new Section_FromEvent_SetContFlag.Description();
				setDesc.pokeID = pokeID;
				setDesc.flag = ContFlag.CONTFLG_KIAIDAME;
				Common.SetContFlag(args, setDesc);
			}
			else
			{
				var resetDesc = new Section_FromEvent_ResetContFlag.Description();
				resetDesc.pokeID = pokeID;
				resetDesc.flag = ContFlag.CONTFLG_KIAIDAME;
				Common.ResetContFlag(args, resetDesc);
			}
			if (target.CheckSick(WazaSick.WAZASICK_TOGISUMASU))
			{
				var sickDesc = new Section_AddSick.Description();
				sickDesc.pokeID = pokeID;
				sickDesc.targetPokeID = pokeID;
				sickDesc.sickID = WazaSick.WAZASICK_TOGISUMASU;
				sickDesc.sickCont = target.GetSickCont(WazaSick.WAZASICK_TOGISUMASU);
				Common.AddSick(args, sickDesc);
			}
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.JikoAnji);
			msgDesc.message.AddArg(pokeID);
			msgDesc.message.AddArg(targetPokeID);
			Common.Message(args, msgDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
