		}
		public static void handler_HeartSwap(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			int[] userRanks = new int[7];
			userRanks[0] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK);
			userRanks[1] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK);
			userRanks[2] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK);
			userRanks[3] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK);
			userRanks[4] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK);
			userRanks[5] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_HIT_RATIO);
			userRanks[6] = user.GetValue(BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO);
			// 0180e6b4: the user's critical rank is read here and given back to the USER (critical ranks are not swapped)
			byte userCritical = user.GetCriticalRankPure();

			var userDesc = new Section_FromEvent_RankSet.Description();
			userDesc.pokeID = pokeID;
			userDesc.attack = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK);
			userDesc.defence = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK);
			userDesc.sp_attack = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK);
			userDesc.sp_defence = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK);
			userDesc.agility = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK);
			userDesc.hit_ratio = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_HIT_RATIO);
			userDesc.avoid_ratio = (byte)target.GetValue(BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO);
			userDesc.critical_rank = userCritical;
			Common.RankSet(args, userDesc);

			var targetDesc = new Section_FromEvent_RankSet.Description();
			targetDesc.pokeID = targetPokeID;
			targetDesc.attack = (byte)userRanks[0];
			targetDesc.defence = (byte)userRanks[1];
			targetDesc.sp_attack = (byte)userRanks[2];
			targetDesc.sp_defence = (byte)userRanks[3];
			targetDesc.agility = (byte)userRanks[4];
			targetDesc.hit_ratio = (byte)userRanks[5];
			targetDesc.avoid_ratio = (byte)userRanks[6];
			targetDesc.critical_rank = target.GetCriticalRankPure();
			Common.RankSet(args, targetDesc);

			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.HeartSwap);
			msgDesc.message.AddArg(pokeID);
			Common.Message(args, msgDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
