		public static void handler_PowerShare(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			// signed halving (`+1` for negatives, then `asr`)
			int attack = (user.GetValue_Base(BTL_POKEPARAM.ValueID.BPP_ATTACK) + target.GetValue_Base(BTL_POKEPARAM.ValueID.BPP_ATTACK)) / 2;
			int spAttack = (user.GetValue_Base(BTL_POKEPARAM.ValueID.BPP_SP_ATTACK) + target.GetValue_Base(BTL_POKEPARAM.ValueID.BPP_SP_ATTACK)) / 2;
			var targetDesc = new Section_FromEvent_SetPower.Description();
			targetDesc.pokeID = targetPokeID;
			targetDesc.attack = (ushort)attack;
			targetDesc.spAttack = (ushort)spAttack;
			targetDesc.isAttackEnable = true;
			targetDesc.isSpAttackEnable = true;
			Common.SetPower(args, targetDesc);
			var userDesc = new Section_FromEvent_SetPower.Description();
			userDesc.pokeID = pokeID;
			userDesc.attack = (ushort)attack;
			userDesc.spAttack = (ushort)spAttack;
			userDesc.isAttackEnable = true;
			userDesc.isSpAttackEnable = true;
			userDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.PowerShare);
			userDesc.successMessage.AddArg(pokeID);
			Common.SetPower(args, userDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
