		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Dokudoku() {
			return HandlerTable_Dokudoku;
		}
		public static void handler_Dokudoku(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			// a Poison-type user never misses with Toxic
			if (!Common.GetPokeParam(args, pokeID).IsMatchType((byte)PokeType.DOKU))
				return;
			var desc = new Section_AddSick.Description();
			desc.pokeID = pokeID;
			desc.targetPokeID = pokeID;
			desc.sickID = WazaSick.WAZASICK_MUSTHIT;
			desc.sickCont = SICKCONT.MakeTurn(pokeID, 1);
			if (Common.AddSick(args, desc))
				Common.SetWorkValue(args, 0, 1);
		}
		public static void handler_Dokudoku_Done(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetWorkValue(args, 0) == 0)
				return;
			var desc = new Section_CureSick.Description();
			desc.pokeID = pokeID;
			desc.targetPokeCount = 1;
			desc.targetPokeID[0] = pokeID;
			desc.sick = (WazaSickEx)WazaSick.WAZASICK_MUSTHIT;
			desc.isStandardMessageDisable = true;
			Common.CureSick(args, desc);
		}
