		public static void handler_WideGuard_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (!Common.CheckPokeOrderLast(args, pokeID))
				return;
			if (Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.OTHER))
			{
				var desc = new Section_FromEvent_SetCounter.Description();
				desc.pokeID = pokeID;
				desc.counterID = (byte)BTL_POKEPARAM.Counter.COUNTER_MAMORU;
				desc.value = 0;
				Common.SetPokeCounter(args, desc);
			}
		}
		public static void handler_WideGuard(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			BTL_SICKCONT cont = SICKCONT.MakeTurn(pokeID, 1);
			BtlSide side = Common.PokeIDtoSide(args, pokeID);
			bool result = common_SideEffectStdMsg(args, pokeID, side, BtlSideEffect.BTL_SIDEEFF_WIDEGUARD, cont, BTL_STRID_STD.WideGuard);
			IncrementMamoruCounter(args, pokeID);
			if (result)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
