		public static void handler_TatamiGaeshi_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.CheckActionDoneOnce(args, pokeID))
				Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.OTHER);
			if (Common.CheckPokeOrderLast(args, pokeID))
				Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.OTHER);
		}
