			BtlSide side = Common.PokeIDtoSide(args, pokeID);
			var sideDesc = new Section_SideEffect_Add.Description();
			sideDesc.pokeID = pokeID;
			sideDesc.effect = BtlSideEffect.BTL_SIDEEFF_TATAMIGAESHI;
			sideDesc.side = side;
