			if (Common.AddSideEffect(args, sideDesc))
			{
				var msgDesc = new Section_FromEvent_Message.Description();
				msgDesc.pokeID = pokeID;
				msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TatamiGaeshi);
				msgDesc.message.AddArg(pokeID);
				Common.Message(args, msgDesc);
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
			}
		}
		public static bool common_SideEffectStdMsg(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID, global::Dpr.Battle.Logic.BtlSide side, global::Dpr.Battle.Logic.BtlSideEffect effect, in global::Dpr.Battle.Logic.BTL_SICKCONT cont, ushort strID) {
