		public static bool common_SideEffectCore(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BtlSide side, global::Dpr.Battle.Logic.BtlSideEffect effect, in global::Dpr.Battle.Logic.BTL_SICKCONT cont, global::Dpr.Battle.Logic.BtlStrType strType, uint strID, int strArg, bool replaceStrArg0ByExpandSide) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return false;
			var desc = new Section_SideEffect_Add.Description();
			desc.pokeID = pokeID;
			desc.effect = effect;
			desc.side = side;
			desc.cont = cont;
			desc.isReplaceSuccessMessageArgs0ByExpandSide = replaceStrArg0ByExpandSide;
			desc.successMessage.Setup(strType, (ushort)strID);
			desc.successMessage.AddArg(strArg);
			return Common.AddSideEffect(args, desc);
		}
