		public static void common_delayAttack(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.BtlPokePos targetPos) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (!Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, TRUE))
				return;
			BtlPokePos basePos = Common.PokeIDtoPokePos(args, pokeID);
			if (targetPos == BtlPokePos.POS_NULL)
			{
				targetPos = Common.GetOpponentPokePos(args, basePos, 0);
				Common.RewriteEventVar(args, EventVar.Label.POKEPOS, (int)targetPos);
			}
			var desc = new Section_FromEvent_PosEffect_Add.Description();
			desc.effect = BtlPosEffect.BTL_POSEFF_DELAY_ATTACK;
			desc.pos = targetPos;
			desc.userPokeID = pokeID;
			desc.effectParam.DelayAttack_execTurnMax = 2;
			desc.effectParam.DelayAttack_execTurnCount = 0;
			desc.effectParam.DelayAttack_wazaNo = Common.GetSubID(args);
			if (Common.AddPosEffect(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
