		}
		public static void handler_TonboGaeri(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (!Common.IsExistBenchPoke(args, pokeID))
				return;
			if (Common.IsExistPokeChangeRequest(args))
				return;
			byte clientID = MainModule.PokeIDtoClientID(pokeID);
			var changeDesc = new Section_FromEvent_MemberChange.Description();
			changeDesc.outPokeID = pokeID;
			changeDesc.startMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Tonbogaeri);
			changeDesc.startMessage.AddArg(pokeID);
			changeDesc.startMessage.AddArg(clientID);
			if (Common.MemberChange(args, changeDesc))
			{
				var viewDesc = new Section_FromEvent_AddViewEffect.Description();
				viewDesc.effectNo = (ushort)(Common.GetSubID(args) == (ushort)WazaNo.TONBOGAERI ? BtlEff.BTLEFF_TONBOGAERI_RETURN : BtlEff.BTLEFF_VOLTCHANGE_RETURN);
				viewDesc.pos_from = Common.PokeIDtoPokePos(args, pokeID);
				viewDesc.pos_to = BtlPokePos.POS_NULL;
				Common.AddViewEffect(args, viewDesc);
			}
		}
