			return HandlerTable_KousokuSpin;
		}
		public static void handler_KousokuSpin(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.CheckSick(WazaSick.WAZASICK_YADORIGI))
			{
				var cureDesc = new Section_CureSick.Description();
				cureDesc.targetPokeCount = 1;
				cureDesc.pokeID = pokeID;
				cureDesc.targetPokeID[0] = pokeID;
				cureDesc.sick = (WazaSickEx)WazaSick.WAZASICK_YADORIGI;
				Common.CureSick(args, cureDesc);
			}
			if (bpp.CheckSick(WazaSick.WAZASICK_BIND))
			{
				var cureDesc = new Section_CureSick.Description();
				cureDesc.targetPokeCount = 1;
				cureDesc.pokeID = pokeID;
				cureDesc.targetPokeID[0] = pokeID;
				cureDesc.sick = (WazaSickEx)WazaSick.WAZASICK_BIND;
				Common.CureSick(args, cureDesc);
			}
			var removeDesc = new Section_SideEffect_Remove.Description();
			removeDesc.pokeID = pokeID;
			removeDesc.side = Common.PokeIDtoSide(args, pokeID);
			calc.BITFLG_Construction(removeDesc.flags);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_MAKIBISI);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_DOKUBISI);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_STEALTHROCK);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_STEALTHROCK_HAGANE);
			calc.BITFLG_Set(removeDesc.flags, (uint)BtlSideEffect.BTL_SIDEEFF_NEBANEBANET);
			Common.RemoveSideEffect(args, removeDesc);
		}
