		public static bool teleport_isQuitBattle(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, in byte pokeID) {
			if (!Common.IsEscapeEnableBattle(args))
				return false;
			if (Common.GetCompetitor(args) != BtlCompetitor.BTL_COMPETITOR_WILD)
				return false;
			BtlSide side = Common.PokeIDtoSide(args, pokeID);
			return !Common.IsPlayerSide(args, side);
		}
		public static bool teleport_canQuitBattle(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, ref global::Dpr.Battle.Logic.WazaFailCause pFailCause, in byte pokeID) {
			// 018132e0: every failed test lands on one tail (`mov w8, #0x27 ; strb w8, [x19]` @0181348c)
			if (Common.GetCompetitor(args) == BtlCompetitor.BTL_COMPETITOR_WILD && Common.GetRule(args) == BtlRule.BTL_RULE_SINGLE)
			{
				BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
				var desc = new Section_Escape_CheckForceSucceed.Description();
				desc.poke = bpp;
				if (Common.CanForceEscape(args, desc))
					return true;
				if (!bpp.CheckSick(WazaSick.WAZASICK_BIND) && !bpp.CheckSick(WazaSick.WAZASICK_TOOSENBOU) && !Common.CheckFieldEffect(args, EffectType.EFF_FAIRY_LOCK))
					return true;
			}
			pFailCause = WazaFailCause.OTHER;
			return false;
		}
		public static void handler_Teleport_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (teleport_isQuitBattle(args, pokeID))
				handler_Teleport_ExeCheck_QuitBattle(args, pokeID);
			else
				handler_Teleport_ExeCheck_ChangePokemon(args, pokeID);
		}
		public static void handler_Teleport_ExeCheck_QuitBattle(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			WazaFailCause failCause = WazaFailCause.NONE;
			if (!teleport_canQuitBattle(args, ref failCause, pokeID))
				Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)failCause);
		}
		public static void handler_Teleport_ExeCheck_ChangePokemon(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.IsExistBenchPoke(args, pokeID) && !Common.IsExistPokeChangeRequest(args))
				return;
			Common.RewriteEventVar(args, EventVar.Label.FAIL_CAUSE, (int)WazaFailCause.OTHER);
		}
