		public static void handler_Nagetukeru_DmgProcStart(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			ushort item = bpp.GetItem();
			if (item == 0)
				return;
			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Nagetukeru);
			msgDesc.message.AddArg(atkPokeID);
			msgDesc.message.AddArg(item);
			Common.Message(args, msgDesc);

			var flagDesc = new Section_FromEvent_SetTurnFlag.Description();
			flagDesc.pokeID = pokeID;
			flagDesc.flag = BTL_POKEPARAM.TurnFlag.TURNFLG_NAGETUKERU_USING;
			Common.SetTurnFlag(args, flagDesc);
		}
		public static void handler_Nagetukeru_DmgAfter(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			ushort item = bpp.GetItem();
			if (item == 0)
				return;
			var consumeDesc = new Section_FromEvent_ConsumeItem.Description();
			consumeDesc.userPokeID = pokeID;
			consumeDesc.isUseActionDisable = true;
			consumeDesc.isKinomiCheckDisable = true;
			Common.ConsumeItem(args, consumeDesc);
			Common.SetWorkValue(args, 0, 1);
			if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
				return;
			if (Common.GetEventVar(args, EventVar.Label.RINPUNGUARD_FLG) != 0)
				return;
			if (calc.ITEM_GetParam(item, Pml.Item.ItemData.PrmID.NAGE_EFF) == 0)
				return;
			var useDesc = new Section_FromEvent_UseItem_Force.Description();
			useDesc.userPokeID = pokeID;
			useDesc.targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			useDesc.itemID = item;
			useDesc.isAteKinomi = true;
			Common.UseItem_Force(args, useDesc);
		}
		public static void handler_Nagetukeru_Done(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetWorkValue(args, 0) != 0)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.GetItem() == 0)
				return;
			var desc = new Section_FromEvent_ConsumeItem.Description();
			desc.userPokeID = pokeID;
			desc.isUseActionDisable = true;
			desc.isKinomiCheckDisable = true;
			Common.ConsumeItem(args, desc);
		}
