		public static void handler_DenjiFuyuu_CheckFail(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			WazaFailCause cause;
			if (bpp.CheckSick(WazaSick.WAZASICK_NEWOHARU) || bpp.CheckSick(WazaSick.WAZASICK_FLYING_CANCEL))
				cause = WazaFailCause.OTHER;
			else if (Common.CheckFieldEffect(args, EffectType.EFF_JURYOKU))
				cause = WazaFailCause.JURYOKU;
			else
				return;
			Common.RewriteEventVar_FAIL_CAUSE(args, cause);
		}
