		public static void handler_Tedasuke_Ready(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			// 018148d0: tedasuke_IsSuccess inlined (its flag in the body)
			if (!tedasuke_IsSuccess(args, pokeID))
				return;
			int targetPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)targetPokeID);
			if (target.IsDead() || target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_ACTION_DONE))
				return;
			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Tedasuke);
			desc.message.AddArg(atkPokeID);
			desc.message.AddArg((byte)targetPokeID);
			Common.Message(args, desc);
			Common.SetWorkValue(args, 0, (byte)targetPokeID);
			Common.ConvertForIsolate(args);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
		public static bool tedasuke_IsSuccess(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			return args.pMainModule.GetFrontPosNum(MainModule.PokeIDtoClientID(pokeID)) > 1;
		}
