		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_FukuroDataki() {
			return HandlerTable_FukuroDataki;
		}
		public static void handler_FukuroDataki(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// 01814e58..01814f60: six unrolled calls (constant party bound), int counter (`cmp w8, #0` unmasked)
			int hitCount = 0;
			for (byte i = 0; i < DefineConstants.BTL_PARTY_MEMBER_MAX; i++)
			{
				if (common_FukuroDataki_GetParam(args, pokeID, i) != null)
					hitCount++;
			}
			if (hitCount == 0)
				hitCount = 1;
			Common.RewriteEventVar(args, EventVar.Label.HITCOUNT, hitCount);
			Common.SetWorkValue(args, 0, 0);
		}
		public static void handler_FukuroDataki_Pow(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			int idx = Common.GetWorkValue(args, 0);
			BTL_POKEPARAM bpp = common_FukuroDataki_GetParam(args, pokeID, (byte)idx);
			if (bpp == null)
				bpp = Common.GetPokeParam(args, pokeID);
			// 018151f4: `csinc w20, wzr, w21, ge` — the next index wraps to 0 at 6
			Common.SetWorkValue(args, 0, idx + 1 < 6 ? idx + 1 : 0);
			// 01815238: unsigned divide (`umull` by 0xcccccccd)
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, (int)((uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MONS_POW) / 10 + 5));
		}
		public static global::Dpr.Battle.Logic.BTL_POKEPARAM common_FukuroDataki_GetParam(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte myPokeID, byte idx) {
			BTL_PARTY party = Common.GetPartyData(args, myPokeID);
			int memberCount = party.GetMemberCount();
			// 0181504c: `cmp count, idx ; b.ls` -> null before the loop
			if (idx >= memberCount)
				return null;
			for (int i = 0; i < memberCount; i++)
			{
				BTL_POKEPARAM bpp = party.GetMemberDataConst((byte)i);
				if (bpp.GetID() == myPokeID || (bpp.IsFightEnable() && bpp.GetPokeSick() == Pml.PokePara.Sick.NONE))
				{
					if (idx == 0)
						return bpp;
					idx--;
				}
			}
			return null;
		}
