			setDesc.successMessage.AddArg(itemno);
			if (Common.SetItem(args, setDesc))
			{
				var useDesc = new Section_FromEvent_UseItem_Force.Description();
				useDesc.userPokeID = pokeID;
				useDesc.targetPokeID = pokeID;
				useDesc.itemID = itemno;
				useDesc.isAteKinomi = true;
				Common.UseItem_Force(args, useDesc);
