		public static void handler_Michidure_WazaDamage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int defPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			if (defPokeID != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.IsDead())
				return;
			if (!tables.IsDelayAttackWaza((WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID)))
			{
				byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
				BTL_POKEPARAM attacker = Common.GetPokeParam(args, atkPokeID);
				if (!Common.IsFriendPokeID(args, pokeID, atkPokeID) && !attacker.IsDead() && !attacker.IsGMode())
				{
					Common.ConvertForIsolate(args);
					var killDesc = new Section_FromEvent_Kill.Description();
					killDesc.userPokeID = atkPokeID;
					killDesc.targetPokeID = pokeID;
					killDesc.deadCause = DamageCause.WAZA;
					killDesc.recordWazaID = (WazaNo)Common.GetEventVar(args, EventVar.Label.ORG_WAZAID);
					killDesc.isDeadPokeEnable = true;
					Common.Kill(args, killDesc);

					var selfKillDesc = new Section_FromEvent_Kill.Description();
					selfKillDesc.userPokeID = pokeID;
					selfKillDesc.targetPokeID = atkPokeID;
					selfKillDesc.deadCause = DamageCause.MITIDURE;
					selfKillDesc.recordWazaID = (WazaNo)Common.GetSubID(args);
					selfKillDesc.isDisableDeadProcess = true;
					selfKillDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.MichidureDone);
					selfKillDesc.message.AddArg(defPokeID);
					Common.Kill(args, selfKillDesc);
				}
			}
			removeMitidureFactor(args, pokeID);
		}
