		public static void handler_Onnen_WazaDamage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;
			if (tables.IsDelayAttackWaza((WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID)))
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.IsDead())
				return;
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			BTL_POKEPARAM attacker = Common.GetPokeParam(args, (byte)atkPokeID);
			int orgWazaID = Common.GetEventVar(args, EventVar.Label.ORG_WAZAID);
			byte wazaIdx = attacker.WAZA_SearchIdx((WazaNo)orgWazaID);
			if (wazaIdx != BattleDefConst.PTL_WAZA_MAX)
			{
				var desc = new Section_FromEvent_DecrementPP.Description();
				desc.pokeID = (byte)atkPokeID;
				desc.wazaIdx = wazaIdx;
				desc.volume = (byte)-attacker.WAZA_GetPP(wazaIdx);
				desc.isDeadPokeEnable = true;
				desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.OnnenDone);
				desc.successMessage.AddArg((byte)atkPokeID);
				desc.successMessage.AddArg(orgWazaID);
				Common.DecrementPP(args, desc);
			}
			removeOnnenFactor(args, pokeID);
		}
