		public static void handler_SizenNoTikara(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			// 01818cb0: rodata table @03d0d6e0 indexed by ground - 1 (byte compare < 4) = {412, 585, 85, 94}
			WazaNo waza;
			switch (Common.GetGround(args))
			{
				case BtlGround.BTL_GROUND_GRASS:
					waza = WazaNo.ENAZIIBOORU;
					break;
				case BtlGround.BTL_GROUND_MIST:
					waza = WazaNo.MUUNFOOSU;
					break;
				case BtlGround.BTL_GROUND_ELEKI:
					waza = WazaNo._10MANBORUTO;
					break;
				case BtlGround.BTL_GROUND_PHYCHO:
					waza = WazaNo.SAIKOKINESISU;
					break;
				default:
					waza = Common.GetFieldSituation(args).bgComponent.sizennotikaraWazaNo;
					break;
			}
			int targetPos = Common.GetEventVar(args, EventVar.Label.POKEPOS_ORG);
			if ((byte)targetPos == (byte)BtlPokePos.POS_NULL)
				targetPos = (int)Common.DecideWazaTargetAuto(args, pokeID, waza);
			Common.RewriteEventVar(args, EventVar.Label.WAZAID, (int)waza);
			Common.RewriteEventVar(args, EventVar.Label.POKEPOS, (byte)targetPos);
		}
