		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Negoto() {
			return HandlerTable_Negoto;
		}
		public static void handler_Negoto(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.CheckNemuri(BTL_POKEPARAM.NemuriCheckMode.NEMURI_CHECK_INCLUDE_ZETTAINEMURI))
				return;
			WazaNo[] wazaList = Arrays.InitializeWithDefaultInstances<WazaNo>(BattleDefConst.PTL_WAZA_MAX);
			// 01819080: WAZA_GetCount() inlined (+0x3c), byte counters
			byte wazaCount = bpp.WAZA_GetCount();
			byte count = 0;
			for (byte i = 0; i < wazaCount; i++)
			{
				WazaNo waza = bpp.WAZA_GetID(i);
				if (!tables.IsNegotoOmmit(waza) && WAZADATA.IsValid(waza) && !WAZADATA.GetFlag(waza, WazaFlag.TAME))
					wazaList[count++] = waza;
			}
			if (count != 0)
			{
				WazaNo waza = wazaList[(byte)calc.GetRand(count)];
				BtlPokePos targetPos = Common.DecideWazaTargetAuto(args, pokeID, waza);
				Common.RewriteEventVar(args, EventVar.Label.WAZAID, (int)waza);
				Common.RewriteEventVar(args, EventVar.Label.POKEPOS, (int)targetPos);
			}
			else
			{
				Common.RewriteEventVar(args, EventVar.Label.FAIL_FLAG, TRUE);
			}
		}
