		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_AsistPower() {
			return HandlerTable_AsistPower;
		}
		public static void handler_AsistPower(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// InitializeArray @global-metadata 0x669005 = {1, 2, 5, 3, 4, 6, 7}
			BTL_POKEPARAM.ValueID[] rankIDs = new BTL_POKEPARAM.ValueID[]
			{
				BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK,
				BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK,
				BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK,
				BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK,
				BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK,
				BTL_POKEPARAM.ValueID.BPP_HIT_RATIO,
				BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO,
			};
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			int upCount = 0;
			for (int i = 0; i < rankIDs.Length; i++)
			{
				// 01819b90: `bic` of (value - 6) by its sign = only the ups above the neutral rank 6 count
				int diff = bpp.GetValue(rankIDs[i]) - 6;
				if (diff > 0)
					upCount += diff;
			}
			if (upCount != 0)
				Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, Common.GetEventVar(args, EventVar.Label.WAZA_POWER) + upCount * 20);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_HeavyBomber() {
			return HandlerTable_HeavyBomber;
		}
		public static void handler_HeavyBomber(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			var atkDesc = new Section_FromEvent_GetWeight.Description();
			atkDesc.pokeID = pokeID;
			uint atkWeight = Common.GetWeight(args, atkDesc);
			var defDesc = new Section_FromEvent_GetWeight.Description();
			defDesc.pokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			uint defWeight = Common.GetWeight(args, defDesc);
			// 01819df0: unguarded SIGNED `sdiv` (ARM64 yields 0 for a zero divisor)
			int ratio = defWeight != 0 ? (int)atkWeight / (int)defWeight : 0;
			int power;
			if (ratio >= 5)
				power = 120;
			else if (ratio == 4)
				power = 100;
			else if (ratio == 3)
				power = 80;
			else if (ratio == 2)
				power = 60;
			else
				power = 40;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, power);
		}
