			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			ushort atkAgility = common_CalcAgility(args, pokeID);
			ushort defAgility = common_CalcAgility(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF));
			// 0181a040: unguarded `udiv` (ARM64 yields 0 for a zero divisor); ratios 0 and 1 are told apart by comparing the
			// speeds themselves (`csel hi` @0181a0ac), so a zero defender speed gives 60
			uint ratio = defAgility != 0 ? (uint)atkAgility / defAgility : 0;
			int power;
			if (ratio > 3)
				power = 150;
			else if (ratio == 3)
				power = 120;
			else if (ratio == 2)
				power = 80;
			else
				power = defAgility > atkAgility ? 40 : 60;
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, power);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_EchoVoice() {
			return HandlerTable_EchoVoice;
		}
		public static void handler_EchoVoice(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			WazaRec wazaRec = Common.GetWazaRec(args);
			WazaNo waza = (WazaNo)Common.GetSubID(args);
			byte turnCount = Common.GetTurnCount(args);
			int power = 40;
			if (turnCount != 0)
			{
				int count = 0;
				for (int turn = turnCount - 1; turn >= 0; turn--)
				{
					if (!wazaRec.IsUsedWaza(waza, (uint)turn))
						break;
					count++;
				}
				power = count > 3 ? 200 : count * 40 + 40;
			}
			Common.RewriteEventVar(args, EventVar.Label.WAZA_POWER, power);
		}
