		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Mizubitasi() {
			return HandlerTable_Mizubitasi;
		}
		public static void handler_Mizubitasi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// 0181a7f8: `cbz count` then an equality loop = an unsigned count
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			if (targetCount == 0)
				return;
			bool result = false;
			for (int i = 0; i < targetCount; i++)
			{
				byte targetPokeID = (byte)Common.GetEventVar(args, (EventVar.Label)((int)EventVar.Label.POKEID_TARGET1 + i));
				var desc = new Section_FromEvent_ChangePokeType.Description();
				desc.pokeID = targetPokeID;
				desc.nextType = PokeTypePair.MakePure((byte)PokeType.MIZU);
				desc.exTypeCause = BTL_POKEPARAM.ExTypeCause.EXTYPE_CAUSE_NONE;
				BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
				if (!target.IsRaidBoss())
					result |= Common.ChangeType(args, desc);
			}
			if (result)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
