					continue;
				var desc = new Section_FromEvent_ChangeTokusei.Description();
				desc.userPokeID = pokeID;
				desc.targetPokeID = (byte)targetPokeID;
				desc.tokuseiID = TokuseiNo.TANZYUN;
				desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TokuseiChange);
				desc.successMessage.AddArg(targetPokeID);
				desc.successMessage.AddArg((int)TokuseiNo.TANZYUN);
				if (Common.ChangeTokusei(args, desc))
					Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
			}
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_NakamaDukuri() {
			return HandlerTable_NakamaDukuri;
		}
		public static void handler_NakamaDukuri(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			TokuseiNo tokusei = (TokuseiNo)user.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI);
			if (tables.CheckNakamaDukuriFailTokusei(tokusei))
				return;
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			if (targetCount == 0)
				return;
			bool result = false;
			for (int i = 0; i < targetCount; i++)
			{
				// Waza class-init test + getEventVarTarget's flag inside the loop = the helper inlined
				byte targetPokeID = getEventVarTarget(args, i);
				BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
				if (target.IsGMode() || target.IsRaidBoss() || target.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI) == (int)TokuseiNo.NAMAKE)
					continue;
				var desc = new Section_FromEvent_ChangeTokusei.Description();
				desc.userPokeID = pokeID;
				desc.targetPokeID = targetPokeID;
				desc.tokuseiID = tokusei;
				desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TokuseiChange);
				desc.successMessage.AddArg(targetPokeID);
				desc.successMessage.AddArg((ushort)tokusei);
				result |= Common.ChangeTokusei(args, desc);
			}
			if (result)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
