		}
		public static bool common_UtiotosuEffect(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte atkPokeID, byte targetPokeID) {
			if (Common.CheckFreeFallPoke(args, targetPokeID))
				return false;
			BTL_POKEPARAM bppTarget = Common.GetPokeParam(args, targetPokeID);
			bool result = common_UtiotosuEffect_falldown(args, atkPokeID, targetPokeID, bppTarget);
			if (bppTarget.CONTFLAG_Get(ContFlag.CONTFLG_SORAWOTOBU))
			{
				var desc = new Section_FromEvent_TameHideCancel.Description();
				desc.targetPokeID = targetPokeID;
				desc.flag = ContFlag.CONTFLG_SORAWOTOBU;
				if (!result)
				{
					desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Utiotosu);
					desc.successMessage.AddArg(targetPokeID);
				}
				Common.CancelTameHide(args, desc);
			}
			// 0181bbfc: returns the fall-down result
			return result;
		}
		public static bool common_UtiotosuEffect_falldown(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte atkPokeID, byte targetPokeID, global::Dpr.Battle.Logic.BTL_POKEPARAM bppTarget) {
			if (bppTarget.CheckSick(WazaSick.WAZASICK_FREEFALL))
				return false;
			var floatDesc = new Section_CheckFloating.Description();
			floatDesc.target = bppTarget;
			floatDesc.isIncludeHikouType = true;
			// 0181bcf8: not floating -> false (the C dropped the return)
			if (!Common.CheckFloating(args, floatDesc))
				return false;

			var sickDesc = new Section_AddSick.Description();
			sickDesc.pokeID = atkPokeID;
			sickDesc.targetPokeID = targetPokeID;
			sickDesc.sickID = WazaSick.WAZASICK_FLYING_CANCEL;
			sickDesc.sickCont = SICKCONT.MakePermanent(atkPokeID);
			sickDesc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Utiotosu);
			sickDesc.specialMessage.AddArg(targetPokeID);
			Common.AddSick(args, sickDesc);

			if (bppTarget.CheckSick(WazaSick.WAZASICK_FLYING))
			{
				var cureDesc = new Section_CureSick.Description();
				cureDesc.pokeID = atkPokeID;
				cureDesc.targetPokeCount = 1;
				cureDesc.targetPokeID[0] = targetPokeID;
				cureDesc.sick = (WazaSickEx)WazaSick.WAZASICK_FLYING;
				cureDesc.isStandardMessageDisable = true;
				Common.CureSick(args, cureDesc);
			}
			if (bppTarget.CheckSick(WazaSick.WAZASICK_TELEKINESIS))
			{
				var cureDesc = new Section_CureSick.Description();
				cureDesc.pokeID = atkPokeID;
				cureDesc.targetPokeCount = 1;
				cureDesc.targetPokeID[0] = targetPokeID;
				cureDesc.sick = (WazaSickEx)WazaSick.WAZASICK_TELEKINESIS;
				cureDesc.isStandardMessageDisable = true;
				Common.CureSick(args, cureDesc);
			}
			return true;
		}
