			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			// 0181c618: GetWeight() inlined (+0x3a); 1002 and up lose 1000, otherwise the weight becomes 1
			ushort weight = bpp.GetWeight();
			if (weight <= 1)
				return;
			var weightDesc = new Section_FromEvent_SetWeight.Description();
			weightDesc.pokeID = pokeID;
			weightDesc.weight = weight < 1002 ? (ushort)1 : (ushort)(weight - 1000);
			weightDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.BodyPurge);
			weightDesc.successMessage.AddArg(atkPokeID);
			Common.SetWeight(args, weightDesc);

			var flagDesc = new Section_FromEvent_SetContFlag.Description();
			flagDesc.pokeID = pokeID;
			flagDesc.flag = ContFlag.CONTFLG_BODYPURGE;
			Common.SetContFlag(args, flagDesc);
		}
