		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SideChange() {
			return HandlerTable_SideChange;
		}
		public static void handler_SideChange(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetRule(args) != BtlRule.BTL_RULE_DOUBLE)
				return;
			// only without a partner client (multi battles excluded)
			if (args.pMainModule.GetFriendCleintID(MainModule.PokeIDtoClientID(pokeID)) != (byte)BTL_CLIENT_ID.BTL_CLIENT_NULL)
				return;
			BtlPokePos myPos = Common.PokeIDtoPokePos(args, pokeID);
			BtlPokePos friendPos = Common.GetFriendPokePos(args, myPos, 0);
			if (friendPos == myPos)
				friendPos = Common.GetFriendPokePos(args, myPos, 1);
			byte friendPokeID = Common.GetFrontPokeID(args, friendPos);
			if (pokeID == friendPokeID)
				return;
			var desc = new Section_FromEvent_SwapPoke.Description();
			desc.pokeID2 = friendPokeID;
			desc.pokeID1 = pokeID;
			desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.SideChange);
			desc.successMessage.AddArg(pokeID);
			desc.successMessage.AddArg(friendPokeID);
			if (Common.SwapPoke(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
