			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			WazaRec wazaRec = Common.GetWazaRec(args);
			WazaNo pairWaza;
			switch ((WazaNo)Common.GetSubID(args))
			{
				case WazaNo.KUROSUHUREIMU:
					pairWaza = WazaNo.KUROSUSANDAA;
					break;
				case WazaNo.KUROSUSANDAA:
					pairWaza = WazaNo.KUROSUHUREIMU;
					break;
				default:
					return;
			}
			if (wazaRec.GetPrevEffectiveWaza(Common.GetTurnCount(args)) == pairWaza)
			{
				Common.MulEventVar(args, EventVar.Label.WAZA_POWER_RATIO, 0x2000);
				// 0181e4b0: common_SetWazaEffectIndex's flag 0x4cbb8eb = the helper inlined
				common_SetWazaEffectIndex(args, 1);
			}
		}
		public static global::Dpr.Battle.Logic.Handler.Waza.CombiEffectType GetCombiWazaType(global::Pml.WazaNo waza1, global::Pml.WazaNo waza2) {
			// 0181e5d4: CombiTbl is re-read from the static block for every access; exhausted table -> NULL (`mov w0, wzr`)
			for (int i = 0; i < CombiTbl.Length; i++)
			{
				if ((CombiTbl[i].waza1 == waza1 && CombiTbl[i].waza2 == waza2) || (CombiTbl[i].waza1 == waza2 && CombiTbl[i].waza2 == waza1))
					return CombiTbl[i].effect;
			}
			return CombiEffectType.COMBI_EFFECT_NULL;
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_CombiWazaCommon() {
			return HandlerTable_CombiWazaCommon;
		}
		public static void handler_CombiWaza_CheckExe(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (!bpp.CombiWaza_GetParam(out byte combiPokeID, out WazaNo combiUsedWaza))
				return;
			CombiEffectType combiType = GetCombiWazaType((WazaNo)Common.GetSubID(args), combiUsedWaza);
			// the move type is read before the combination test
			int wazaType = Common.GetEventVar(args, EventVar.Label.WAZA_TYPE);
			if (combiType == CombiEffectType.COMBI_EFFECT_NULL)
				return;
			Common.SetWorkValue(args, 0, 1);
			Common.SetWorkValue(args, 1, (int)combiType);
			Common.SetWorkValue(args, 2, combiPokeID);
			// 0181e920: rodata @03d4874c {MIZU, HONOO, KUSA} indexed by effect - 1, else the move's own type (byte)
			int newType;
			switch (combiType)
			{
				case CombiEffectType.COMBI_EFFECT_RAINBOW:
					newType = (int)PokeType.MIZU;
					break;
				case CombiEffectType.COMBI_EFFECT_BURNING:
					newType = (int)PokeType.HONOO;
					break;
				case CombiEffectType.COMBI_EFFECT_MOOR:
					newType = (int)PokeType.KUSA;
					break;
				default:
					newType = (byte)wazaType;
					break;
			}
			Common.RewriteEventVar(args, EventVar.Label.WAZA_TYPE, newType);
		}
