		public static void handler_CombiWaza_ChangeEff(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetWorkValue(args, 0) == 0)
				return;
			// 0181ed2c: effect + 0x205 for effects 1..3 (`sub #1 ; cmp #2 ; csel hi`), else 0
			WazaNo effectWaza;
			switch ((CombiEffectType)Common.GetWorkValue(args, 1))
			{
				case CombiEffectType.COMBI_EFFECT_RAINBOW:
					effectWaza = WazaNo.MIZUNOTIKAI;
					break;
				case CombiEffectType.COMBI_EFFECT_BURNING:
					effectWaza = WazaNo.HONOONOTIKAI;
					break;
				case CombiEffectType.COMBI_EFFECT_MOOR:
					effectWaza = WazaNo.KUSANOTIKAI;
					break;
				default:
					effectWaza = WazaNo.NULL;
					break;
			}
			Common.RewriteEventVar(args, EventVar.Label.EFFECT_WAZAID, (int)effectWaza);
		}
		public static void handler_CombiWaza_AfterDmg(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.GetWorkValue(args, 0) == 0)
				return;
			BtlSide mySide = Common.PokeIDtoSide(args, pokeID);
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BtlSide targetSide = Common.PokeIDtoSide(args, targetPokeID);
			BtlSideEffect effect;
			BtlEff effectNo;
			ushort strID;
			BtlSide side;
			byte viewPokeID;
			switch ((CombiEffectType)Common.GetWorkValue(args, 1))
			{
				case CombiEffectType.COMBI_EFFECT_RAINBOW:
					effect = BtlSideEffect.BTL_SIDEEFF_RAINBOW;
					effectNo = BtlEff.BTLEFF_RAINBOW;
					strID = BTL_STRID_STD.Rainbow;
					side = mySide;
					viewPokeID = pokeID;
					break;
				case CombiEffectType.COMBI_EFFECT_BURNING:
					effect = BtlSideEffect.BTL_SIDEEFF_BURNING;
					effectNo = BtlEff.BTLEFF_BURNING;
					strID = BTL_STRID_STD.Burning;
					side = targetSide;
					viewPokeID = targetPokeID;
					break;
				case CombiEffectType.COMBI_EFFECT_MOOR:
					effect = BtlSideEffect.BTL_SIDEEFF_MOOR;
					effectNo = BtlEff.BTLEFF_MOOR;
					strID = BTL_STRID_STD.Moor;
					side = targetSide;
					viewPokeID = targetPokeID;
					break;
				default:
					return;
			}
			var sideDesc = new Section_SideEffect_Add.Description();
			sideDesc.pokeID = pokeID;
			sideDesc.effect = effect;
			sideDesc.side = side;
			sideDesc.cont = SICKCONT.MakeTurn(pokeID, 4);
			sideDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_STD, strID);
			sideDesc.successMessage.AddArg((int)side);
			Common.AddSideEffect(args, sideDesc);
			if (viewPokeID == PokeID.INVALID)
				return;
			BtlPokePos pos = Common.GetPokeLastPos(args, viewPokeID);
			if (pos == BtlPokePos.POS_NULL)
				return;
			var viewDesc = new Section_FromEvent_AddViewEffect.Description();
			viewDesc.effectNo = (ushort)effectNo;
			viewDesc.pos_from = pos;
			viewDesc.pos_to = BtlPokePos.POS_NULL;
			Common.AddViewEffect(args, viewDesc);
		}
