		public static bool common_GuardUpByPokeType(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte pokeType) {
			// 0181f6f0: `cbz count` then an equality loop = an unsigned count; the OR'd result is returned (0181f88c)
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			bool result = false;
			for (int i = 0; i < targetCount; i++)
			{
				// Waza class-init test + getEventVarTarget's flag inside the loop = the helper inlined
				byte targetPokeID = getEventVarTarget(args, i);
				BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
				if (!target.IsMatchType(pokeType))
					continue;
				var desc = new Section_FromEvent_RankEffect.Description();
				desc.pokeID = pokeID;
				desc.targetPokeCount = 1;
				desc.targetPokeID[0] = targetPokeID;
				desc.rankType = WazaRankEffect.DEFENCE;
				desc.rankVolume = 1;
				desc.isSpFailMessageDisplay = true;
				desc.byWazaEffect = true;
				result |= Common.RankEffect(args, desc);
			}
			return result;
		}
