		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Hikkurikaesu() {
			return HandlerTable_Hikkurikaesu;
		}
		public static void handler_Hikkurikaesu(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			int targetPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)targetPokeID);
			// 0181fc10..0181fd38: each rank read, then 12 - rank stored (bounds-checked) into a 7-int array
			int[] newRank = new int[7];
			int attack = target.GetValue(BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK);
			newRank[0] = 12 - attack;
			int defence = target.GetValue(BTL_POKEPARAM.ValueID.BPP_DEFENCE_RANK);
			newRank[1] = 12 - defence;
			int spAttack = target.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_ATTACK_RANK);
			newRank[2] = 12 - spAttack;
			int spDefence = target.GetValue(BTL_POKEPARAM.ValueID.BPP_SP_DEFENCE_RANK);
			newRank[3] = 12 - spDefence;
			int agility = target.GetValue(BTL_POKEPARAM.ValueID.BPP_AGILITY_RANK);
			newRank[4] = 12 - agility;
			int hitRatio = target.GetValue(BTL_POKEPARAM.ValueID.BPP_HIT_RATIO);
			newRank[5] = 12 - hitRatio;
			int avoidRatio = target.GetValue(BTL_POKEPARAM.ValueID.BPP_AVOID_RATIO);
			newRank[6] = 12 - avoidRatio;
			if (attack == 6 && defence == 6 && spAttack == 6 && spDefence == 6 && agility == 6 && hitRatio == 6 && avoidRatio == 6)
				return;
			var setDesc = new Section_FromEvent_RankSet.Description();
			setDesc.pokeID = (byte)targetPokeID;
			setDesc.attack = (byte)newRank[0];
			setDesc.defence = (byte)newRank[1];
			setDesc.sp_attack = (byte)newRank[2];
			setDesc.sp_defence = (byte)newRank[3];
			setDesc.agility = (byte)newRank[4];
			setDesc.hit_ratio = (byte)newRank[5];
			setDesc.avoid_ratio = (byte)newRank[6];
			setDesc.critical_rank = target.GetCriticalRankPure();
			Common.RankSet(args, setDesc);

			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Hikkurikaesu);
			msgDesc.message.AddArg((byte)targetPokeID);
			Common.Message(args, msgDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
