			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			if (Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT) == 0)
				return;
			if (!Common.IsFriendPokeID(args, pokeID, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1)))
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.CheckSick(WazaSick.WAZASICK_KAIHUKUHUUJI))
				Common.RewriteEventVar_FAIL_CAUSE(args, WazaFailCause.KAIHUKUHUUJI);
