		public static void handler_Kahundango_RecoverCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.IsFriendPokeID(args, pokeID, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF)))
			{
				bool result = Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, TRUE);
				Common.SetWorkValue(args, 0, result ? 1 : 0);
			}
			// 018237c0: common_SetWazaEffectIndex's flag 0x4cbb8eb = the helper inlined
			common_SetWazaEffectIndex(args, (byte)(Common.GetWorkValue(args, 0) != 0 ? 1 : 0));
		}
		public static void handler_Kahundango_RecoverFix(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.GetWorkValue(args, 0) == 0)
				return;
			int targetPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)targetPokeID);
			if (target.IsHPFull())
			{
				var msgDesc = new Section_FromEvent_Message.Description();
				msgDesc.pokeID = pokeID;
				msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.NoEffect);
				msgDesc.message.AddArg((byte)targetPokeID);
				Common.Message(args, msgDesc);
			}
			else
			{
				var recoverDesc = new Section_RecoverHP.Description();
				recoverDesc.userPokeID = pokeID;
				recoverDesc.targetPokeID = (byte)targetPokeID;
				recoverDesc.recoverHP = (ushort)calc.QuotMaxHP(target, 2, true);
				recoverDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.HP_Recover);
				recoverDesc.successMessage.AddArg((byte)targetPokeID);
				Common.RecoverHP(args, recoverDesc);
			}
		}
