		public static bool kuraitukuCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, global::Dpr.Battle.Logic.BTL_POKEPARAM attack, global::Dpr.Battle.Logic.BTL_POKEPARAM target) {
