			return Common.CanAddSick(args, desc);
		}
		public static void kuraitukuSet(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte attackPokeID, byte targetPokeID) {
			var desc = new Section_AddSick.Description();
			desc.pokeID = attackPokeID;
