		public static void handler_Kuraituku(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			// getEventVarTarget(args, 0) inlined (its flag in the body)
			byte targetPokeID = getEventVarTarget(args, 0);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			if (user.IsMatchType((byte)PokeType.GHOST) || target.IsMatchType((byte)PokeType.GHOST))
				return;
			if (!Common.IsExistPoke(args, pokeID) || !Common.IsExistPoke(args, targetPokeID))
				return;
			if (!kuraitukuCheck(args, target, user) || !kuraitukuCheck(args, user, target))
				return;
			kuraitukuSet(args, targetPokeID, pokeID);
			kuraitukuSet(args, pokeID, targetPokeID);
			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Kuraituku);
			Common.Message(args, desc);
		}
