		public static void handler_takoGatame(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			int targetPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)targetPokeID);
			if (target.CheckSick(WazaSick.WAZASICK_TOOSENBOU) || target.CheckSick(WazaSick.WAZASICK_TAKOGATAME) || target.IsMatchType((byte)PokeType.GHOST))
				return;
			var bindDesc = new Section_AddSick.Description();
			bindDesc.pokeID = pokeID;
			bindDesc.targetPokeID = (byte)targetPokeID;
			bindDesc.sickID = WazaSick.WAZASICK_TOOSENBOU;
			bindDesc.sickCont = calc.MakeWazaSickCont_Poke(pokeID, pokeID);
			bool bindResult = Common.AddSick(args, bindDesc);

			var takoDesc = new Section_AddSick.Description();
			takoDesc.pokeID = pokeID;
			takoDesc.targetPokeID = (byte)targetPokeID;
			takoDesc.sickID = WazaSick.WAZASICK_TAKOGATAME;
			takoDesc.sickCont = calc.MakeWazaSickCont_Poke(pokeID, pokeID);
			takoDesc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Takogatame);
			takoDesc.specialMessage.AddArg((byte)targetPokeID);
			bool takoResult = Common.AddSick(args, takoDesc);
			if (bindResult || takoResult)
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Zyouka() {
			return HandlerTable_Zyouka;
		}
		public static void handler_Zyouka(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			if (targetCount == 0)
				return;
			bool cured = false;
			for (int i = 0; i < targetCount; i++)
			{
				// getEventVarTarget inlined (its flag in the body)
				byte targetPokeID = getEventVarTarget(args, i);
				BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
				Pml.PokePara.Sick sick = target.GetPokeSick();
				if (sick == Pml.PokePara.Sick.NONE)
					continue;
				var cureDesc = new Section_CureSick.Description();
				cureDesc.pokeID = pokeID;
				cureDesc.targetPokeID[0] = targetPokeID;
				cureDesc.targetPokeCount = 1;
				cureDesc.sick = (WazaSickEx)sick;
				Common.CureSick(args, cureDesc);
				cured = true;
			}
			if (!cured)
				return;
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			var recoverDesc = new Section_RecoverHP.Description();
			recoverDesc.userPokeID = pokeID;
			recoverDesc.targetPokeID = pokeID;
			recoverDesc.recoverHP = (ushort)calc.QuotMaxHP(user, 2, true);
			recoverDesc.isSkipFailCheckSP = false;
			recoverDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.HP_Recover);
			recoverDesc.successMessage.AddArg(atkPokeID);
			Common.RecoverHP(args, recoverDesc);
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
