			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			if (!target.IsRankEffectValid(BTL_POKEPARAM.ValueID.BPP_ATTACK_RANK, -1))
				return;
			int attack = target.GetValue(BTL_POKEPARAM.ValueID.BPP_ATTACK);
			var rankDesc = new Section_FromEvent_RankEffect.Description();
			rankDesc.pokeID = pokeID;
			rankDesc.targetPokeCount = 1;
			rankDesc.targetPokeID[0] = targetPokeID;
			rankDesc.rankType = WazaRankEffect.ATTACK;
			rankDesc.rankVolume = -1;
			rankDesc.isSpFailMessageDisplay = true;
			rankDesc.byWazaEffect = true;
			Common.RankEffect(args, rankDesc);
			if (attack != 0)
			{
				var drainDesc = new Section_FromEvent_DrainHP.Description();
				drainDesc.recoverPokeID = pokeID;
				drainDesc.damagedPokeID = targetPokeID;
				drainDesc.recoverHP = (ushort)attack;
				drainDesc.isSkipFailCheckSP = false;
				drainDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.HP_Recover);
				drainDesc.successMessage.AddArg(atkPokeID);
				Common.DrainHp(args, drainDesc);
			}
			Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
