		public static void handler_Moetukiru_DamageProcEnd(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			// 01825890: the event var is cast to a byte before the compare (`and #0xff`)
			byte atkPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			PokeTypePair type = bpp.GetPokeType();
			BTL_POKEPARAM.ExTypeCause exTypeCause = bpp.GetExTypeCause();

