			flagDesc.pokeID = pokeID;
			flagDesc.flag = ContFlag.CONTFLG_MOETUKIRU;
			Common.SetContFlag(args, flagDesc);

			type = PokeTypePair.Replace(type, (byte)PokeType.HONOO, (byte)PokeType.NULL);
			// the extra type's cause survives only while an extra type remains
			BTL_POKEPARAM.ExTypeCause nextCause = PokeTypePair.GetTypeEx(type) != (byte)PokeType.NULL ? exTypeCause : BTL_POKEPARAM.ExTypeCause.EXTYPE_CAUSE_NONE;
			var typeDesc = new Section_FromEvent_ChangePokeType.Description();
			typeDesc.pokeID = pokeID;
			typeDesc.nextType = type;
			typeDesc.exTypeCause = nextCause;
			typeDesc.isStandardMessageDisable = true;
			Common.ChangeType(args, typeDesc);

			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Moetukiru);
			msgDesc.message.AddArg(atkPokeID);
			Common.Message(args, msgDesc);
		}
