		public static void handler_TrapShell_DamageProcEnd(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			if (targetCount == 0)
				return;
			// every target is read (no early exit); getEventVarTarget inlined (flag + Waza class-init in the loop)
			bool isTarget = false;
			for (int i = 0; i < targetCount; i++)
				isTarget |= getEventVarTarget(args, i) == pokeID;
			if (!isTarget)
				return;
			if (Common.GetEventVar_DAMAGE_TYPE(args) != WazaDamageType.PHYSIC)
				return;
			if (Common.IsFriendPokeID(args, pokeID, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK)))
				return;
			var desc = new Section_FromEvent_InterruptAction.Description();
			desc.pokeID = pokeID;
			desc.wazano = WazaNo.TORAPPUSHERU;
			Common.InterruptPokeAction(args, desc);
			Common.SetWorkValue(args, 0, 1);
		}
