		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Saihai() {
			return HandlerTable_Saihai;
		}
		public static void handler_Saihai(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			int targetPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)targetPokeID);
			// GetPrevWazaID (+0x4c) / GetPrevOrgWazaID (+0x50) / GetPrevTargetPos are inlined field reads
			if (GWaza.IsGWaza(target.GetPrevWazaID()) || target.IsGMode())
				return;
			WazaNo waza = target.GetPrevOrgWazaID();
			if (tables.IsSaihaiOmmit(waza) || WAZADATA.GetFlag(waza, WazaFlag.TAME) || WAZADATA.GetFlag(waza, WazaFlag.TIRE) || target.WAZA_GetPP_ByNumber(waza) == 0)
				return;
			if (Common.CheckFreeFallPoke(args, (byte)targetPokeID))
				return;
			if (target.CONTFLAG_Get(ContFlag.CONTFLG_CANT_ACTION)
				|| target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_CANT_ACTION)
				|| target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_KIAI_READY)
				|| target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_TRAPPSHELL_READY))
				return;
			var desc = new Section_FromEvent_InsertWazaAction.Description();
			desc.actPokeID = (byte)targetPokeID;
			desc.actWazaNo = waza;
			desc.targetPos = target.GetPrevTargetPos();
			desc.actionDesc.isSaihaiReaction = true;
			desc.actionDesc.insertInfo.prevActionMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Saihai);
			desc.actionDesc.insertInfo.prevActionMessage.AddArg(atkPokeID);
			desc.actionDesc.insertInfo.prevActionMessage.AddArg((byte)targetPokeID);
			if (Common.InsertWazaAction(args, desc))
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, TRUE);
		}
