		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_ShadowSteal() {
			return HandlerTable_ShadowSteal;
		}
		public static void handler_ShadowSteal_DamageProcStart(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			if (Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT) == 0)
				return;
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_TARGET1);
			BTL_POKEPARAM target = Common.GetPokeParam(args, targetPokeID);
			// 018275d0..: `new int[8]` indexed by the rank value IDs 1..7 (element 0 unused), each rank − 6; unrolled in the binary
			int[] rankUp = new int[8];
			bool isRankUp = false;
			for (int vid = (int)BTL_POKEPARAM.ValueID.BPP_RANKVALUE_START; vid <= (int)BTL_POKEPARAM.ValueID.BPP_RANKVALUE_END; vid++)
			{
				rankUp[vid] = target.GetValue((BTL_POKEPARAM.ValueID)vid) - 6;
				if (rankUp[vid] > 0)
					isRankUp = true;
			}
			if (!isRankUp)
				return;
			BTL_POKEPARAM user = Common.GetPokeParam(args, pokeID);
			if (!user.IsWazaHide())
			{
				var viewDesc = new Section_FromEvent_AddViewEffect.Description();
				viewDesc.effectNo = (ushort)BtlEff.BTLEFF_SHADOWSTEAL;
				viewDesc.pos_from = Common.PokeIDtoPokePos(args, pokeID);
				viewDesc.pos_to = Common.PokeIDtoPokePos(args, targetPokeID);
				viewDesc.isMessageWindowVanish = true;
				Common.AddViewEffect(args, viewDesc);
			}
			var flatDesc = new Section_FromEvent_RankFlat_Weaken.Description();
			flatDesc.pokeID = targetPokeID;
			Common.RankFlat_Weaken(args, flatDesc);

			var msgDesc = new Section_FromEvent_Message.Description();
			msgDesc.pokeID = pokeID;
			msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.ShadowSteal);
			msgDesc.message.AddArg(pokeID);
			Common.Message(args, msgDesc);

			// 018278f8..018279b8: a real loop over rank IDs 1..7, every positive stage moved onto the user (byWazaEffect only)
			for (int vid = (int)BTL_POKEPARAM.ValueID.BPP_RANKVALUE_START; vid <= (int)BTL_POKEPARAM.ValueID.BPP_RANKVALUE_END; vid++)
			{
				if (rankUp[vid] <= 0)
					continue;
				var rankDesc = new Section_FromEvent_RankEffect.Description();
				rankDesc.pokeID = pokeID;
				rankDesc.targetPokeID[0] = pokeID;
				rankDesc.targetPokeCount = 1;
				rankDesc.rankType = (WazaRankEffect)vid;
				rankDesc.rankVolume = (sbyte)rankUp[vid];
				rankDesc.byWazaEffect = true;
				Common.RankEffect(args, rankDesc);
			}
		}
