		public static void handler_DaiWall_NoEffectCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) == pokeID)
				return;
			if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
				return;
			if (tables.IsDaiWallGuardDisable((WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID)))
				return;
			Common.RewriteEventVar(args, EventVar.Label.NOEFFECT_FLAG, TRUE);
			Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, TRUE);
			var viewDesc = new Section_FromEvent_AddViewEffect.Description();
			viewDesc.effectNo = (ushort)BtlEff.BTLEFF_GUARD_G;
			viewDesc.pos_from = Common.PokeIDtoPokePos(args, pokeID);
