			StrParam str = (StrParam)Common.GetEventVarAddress(args, EventVar.Label.WORK_ADRS);
			str.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Mamoru);
			str.AddArg(pokeID);
		}
