		public static void handler_HaisuiNoJin_ExeCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.CONTFLAG_Get(ContFlag.CONTFLG_HAISUINOZIN))
				Common.RewriteEventVar_FAIL_CAUSE(args, WazaFailCause.OTHER);
		}
		public static void handler_HaisuiNoJin(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int myPokeID = Common.GetEventVar(args, EventVar.Label.POKEID);
			if (myPokeID != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			if (bpp.CheckSick(WazaSick.WAZASICK_TOOSENBOU))
				return;
			var sickDesc = new Section_AddSick.Description();
			sickDesc.pokeID = pokeID;
			sickDesc.targetPokeID = pokeID;
			sickDesc.sickID = WazaSick.WAZASICK_TOOSENBOU;
			sickDesc.sickCont = SICKCONT.MakePermanent(pokeID);
			sickDesc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Haisuinozin);
			sickDesc.specialMessage.AddArg(myPokeID);
			Common.AddSick(args, sickDesc);

			var flagDesc = new Section_FromEvent_SetContFlag.Description();
			flagDesc.pokeID = pokeID;
			flagDesc.flag = ContFlag.CONTFLG_HAISUINOZIN;
			Common.SetContFlag(args, flagDesc);
		}
