			return HandlerTable_SoulBeat;
		}
		public static void handler_SoulBeat_CheckExe(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			int hp = bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
			// 018288a8: UNSIGNED compare (`b.ls`)
			if ((uint)hp <= calc.QuotMaxHP(bpp, 3, true))
				Common.RewriteEventVar_FAIL_CAUSE(args, WazaFailCause.OTHER);
		}
		public static void handler_SoulBeat_Damage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
			uint cost = calc.QuotMaxHP(bpp, 3, true);
			var desc = new Section_FromEvent_ShiftHP.Description();
			desc.pokeID = pokeID;
			desc.targetPokeCount = 1;
			desc.targetPokeID[0] = pokeID;
			desc.volume[0] = -(int)cost;
			desc.damageCause = DamageCause.OTHER;
			Common.ShiftHP(args, desc);
		}
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Ochakai() {
			return HandlerTable_Ochakai;
		}
		public static bool ochakai_EatNuts(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			ushort itemID = Common.GetPokeParam(args, pokeID).GetItem();
			if (!Pml.Item.ItemData.IsNuts(itemID))
				return false;
			var setItemDesc = new Section_FromEvent_SetItem.Description();
			setItemDesc.userPokeID = pokeID;
			setItemDesc.targetPokeID = pokeID;
			setItemDesc.itemID = 0;
			setItemDesc.isConsumeItem = true;
			Common.SetItem(args, setItemDesc);
			var useItemDesc = new Section_FromEvent_UseItem_Force.Description();
			useItemDesc.userPokeID = pokeID;
			useItemDesc.targetPokeID = pokeID;
			useItemDesc.itemID = itemID;
			useItemDesc.isAteKinomi = true;
			useItemDesc.useEffectType = Section_FromEvent_UseItem_Force.UseEffectType.Force;
			Common.UseItem_Force(args, useItemDesc);
			return true;
		}
		public static void handler_Ochakai(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			if (Common.GetEventVar(args, EventVar.Label.POKEID_ATK) != pokeID)
				return;
			var desc = new Section_FromEvent_Message.Description();
			desc.pokeID = pokeID;
			desc.message.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ochakai);
			Common.Message(args, desc);
			uint targetCount = (uint)Common.GetEventVar(args, EventVar.Label.TARGET_POKECNT);
			bool isEat = false;
			for (int i = 0; i < targetCount; i++)
			{
				// getEventVarTarget inlined (its init flag 0x4cbb8ea @01828da8)
				isEat |= ochakai_EatNuts(args, getEventVarTarget(args, i));
			}
			if (isEat)
			{
				Common.RewriteEventVar(args, EventVar.Label.SUCCESS_FLAG, 1);
				return;
			}
			var failDesc = new Section_FromEvent_Message.Description();
			failDesc.pokeID = pokeID;
			failDesc.message.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Ochakai_Failed);
			Common.Message(args, failDesc);
			Common.RewriteEventVar(args, EventVar.Label.GEN_FLAG, 0);
		}
