				return;
			BTL_POKEPARAM target = Common.GetPokeParam(args, (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF));
			if (!target.TURNFLAG_Get(BTL_POKEPARAM.TurnFlag.TURNFLG_ACTION_DONE))
				Common.MulWazaBasePower(args, 2);
		}
