		public static void handler_TarShot_Str(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			if (Common.GetEventVar(args, EventVar.Label.SICKID) != (int)WazaSick.WAZASICK_TAR)
				return;
			byte defPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			StrParam strParam = (StrParam)Common.GetEventVarAddress(args, EventVar.Label.WORK_ADRS);
			strParam.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.TarShot);
			strParam.AddArg(defPokeID);
			strParam.AddArg(atkPokeID);
		}
