		public static void handler_DragonArrow_Inc(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
			int atkPokeID = Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
			if (atkPokeID != pokeID)
				return;
			byte defPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_DEF);
			byte targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID);
			if (atkPokeID == targetPokeID)
				return;
			if (Common.IsFriendPokeID(args, targetPokeID, defPokeID))
				Common.RewriteEventVar(args, EventVar.Label.ENABLE_FLAG, 1);
