			// 018295dc: common_IsMyEvent inlined (Waza class-init test, direct EVENTVAR_GetValue reads, no flag)
			if (!common_IsMyEvent(args, EventVar.Label.POKEID_ATK, pokeID))
				return;
			if (Common.GetRule(args) != BtlRule.BTL_RULE_RAID)
				return;
			StrParam strParam = (StrParam)Common.GetEventVarAddress(args, EventVar.Label.WORK_ADRS);
			strParam.Clear();
		}
